NAME = 'GerGruenewald: 1924 Grünewaldbibel'
BOOK = 'Acts'

CHAPTERS = {
    1: {
        1: 'Lieber Theophilus! In meiner ersten Schrift habe ich von allem erzählt, was Jesus tat und lehrte',
        2: 'bis zu jenem Tage, da er in den Himmel aufgenommen ward, nachdem er den Aposteln, die er sich durch den Heiligen Geist auserwählt hatte, seinen Willen kundgetan.',
        3: 'Diesen hatte er sich auch nach seinem Leiden als lebendig dargestellt durch vielerlei Beweise: Vierzig Tage hindurch erschien er ihnen, wobei er ihnen über alles Aufschluß gab, was das Reich Gottes betrifft.',
        4: 'Als er mit ihnen noch zusammen war, befahl er ihnen, von Jerusalem nicht wegzugehen, sondern abzuwarten, was der Vater verheißen hat: "Was ihr von mir gehört habt so sprach er:',
        5: '"Johannes hat zwar mit Wasser getauft, ihr aber sollt in eben diesen Tagen mit dem Heiligen Geiste getauft werden."',
        6: 'Die zusammengekommen waren, fragten ihn: "Herr, wirst du in dieser Zeit die Königsherrschaft in Israel wiederherstellen?"',
        7: 'Doch er sprach zu ihnen: "Nicht eure Sache ist es, Zeit und Stunde zu erfahren die der Vater in seiner Machtvollkommenheit festgesetzt hat.',
        8: 'Ihr werdet jedoch Kraft empfangen, wenn der Heilige Geist über euch herabkommt, und ihr werdet für mich zu Zeugen werden in Jerusalem, in ganz Judäa und in Samaria, ja, bis an die Grenzen der Erde."',
        9: 'Nach diesen Worten ward er vor ihren Augen emporgehoben, und eine Wolke entrückte ihn ihren Blicken.',
        10: 'Unverwandten Auges schauten sie gen Himmel, während er emporfuhr. Doch siehe, da standen zwei Männer in weißen Gewändern bei ihnen.',
        11: 'Sie sprachen: "Ihr Galiläer! Was steht ihr da und schaut zum Himmel hinauf? Dieser Jesus, der aus eurer Mitte in den Himmel aufgenommen ward, wird in derselben Weise wiederkommen, wie ihr ihn in den Himmel habt auffahren sehen."',
        12: 'Darauf kehrten sie von dem Berge, der Ölberg heißt und nahe bei Jerusalem liegt, einen Sabbatweg entfernt, nach Jerusalem zurück.',
        13: 'Dort angekommen, begaben sie sich in das Obergemach, wo sie blieben: nämlich Petrus und Johannes, Jakobus und Andreas, Philippus und Thomas, Bartholomäus und Matthäus, Jakobus, der Sohn des Alphäus, und Simon, der Eiferer, und Judas, der Bruder des Jakobus.',
        14: 'Sie alle verharrten einmütig im Gebet mit den Frauen, mit Maria, der Mutter Jesu, und mit seinen Brüdern.',
        15: 'In jenen Tagen erhob sich Petrus inmitten der Brüder - es war eine Menge von ungefähr einhundertzwanzig Personen beisammen - und sprach:',
        16: '"Liebe Brüder! Das Schriftwort mußte in Erfüllung gehen, das der Heilige Geist durch den Mund Davids über Judas vorhergesagt, der den Häschern Jesu den Weg gezeigt hatte.',
        17: 'Er gehörte einst zu uns und hatte teil an diesem Amt erhalten.',
        18: 'Um seinen Sündenlohn erwarb er sich einen Acker, fiel dann kopfüber ab und barst entzwei, und alle seine Eingeweide quollen hervor.',
        19: 'Und dies erfuhren alle Einwohner Jerusalems; darum nannten sie in ihrer Sprache jenen Acker: Hakeldama, d.h. Blutacker.',
        20: "Heißt es doch im Buch der Psalmen: 'Seine Wohnstatt werde öde, und niemand sei, der darin wohne!' Und dann: 'Sein Amt soll ein anderer erhalten!'",
        21: 'So muß denn einer von den Männern, die bei uns waren in der ganzen Zeit, da der Herr Jesus bei uns ein- und ausging,',
        22: 'angefangen von der Taufe des Johannes bis zu dem Tage, da er von uns hinweg aufgenommen ward, es muß von diesen einer mit uns Zeuge seiner Auferstehung werden."',
        23: 'Sie stellten zwei vor: Joseph, genannt Barsabas, mit dem Beinamen Justus, und Matthias.',
        24: 'Und sie beteten: "O Herr, Du kennst die Herzen aller, zeige an, wen von diesen beiden Du erwählt hast,',
        25: 'die Stelle dieses Dienstes und Apostelamtes zu erhalten, von dem Judas abgefallen war, um an seinen Ort zu gehen."',
        26: 'Dann warfen sie das Los für sie, und das Los fiel auf Matthias. Er wurde den elf Aposteln beigezählt.',
    },
    2: {
        1: 'So war das Pfingstfest herangekommen. Alle waren an demselben Ort beisammen.',
        2: 'Plötzlich erhob sich vom Himmel her ein Brausen, als ob ein gewaltiger Wind daherkäme, und erfüllte das ganze Haus, in dem sie saßen.',
        3: 'Es erschienen ihnen Zungen, wie von Feuer, die sich verteilten und sich auf jeden einzelnen unter ihnen niederließen.',
        4: 'Alle wurden voll des Heiligen Geistes und begannen, in fremden Sprachen zu reden, wie es der Heilige Geist ihnen verlieh zu sprechen.',
        5: 'In Jerusalem wohnten aber Juden, gottesfürchtige Männer, aus allen Völkern unter dem Himmel.',
        6: 'Als sich nun dieses Brausen erhob, lief die Menge zusammen und wurde bestürzt, weil ein jeder sie in seiner Muttersprache reden hörte.',
        7: 'Außer sich vor Verwunderung riefen sie: "Sind denn nicht alle, die da reden, Galiläer?',
        8: 'Wie mag es denn geschehen, daß jeder aus uns sie in seiner Muttersprache reden hört?',
        9: 'Wir Parther, Meder und Elamiter, und wir, die wir Mesopotamien bewohnen. Judäa und Kappadozien, Pontus und Asien.',
        10: 'Phrygien und Pamphilien, Ägypten und den Landstrich Lybiens bis nach Cyrene hin, wir Pilger aus Rom,',
        11: 'Juden und Proselyten, wir Kreter und Araber, wir hören sie in unseren Sprachen die großen Taten Gottes verkünden."',
        12: 'Alle waren außer sich vor Staunen und sprachen zueinander: "Was mag das wohl sein?"',
        13: 'Andere dagegen spotteten und sagten: "Sie sind voll süßen Weines."',
        14: 'Da trat Petrus samt den Elfen vor, erhob seine Stimme und redete sie begeistert an: "Ihr Männer von Judäa und ihr alle, die ihr in Jerusalem zu Hause seid! Dies sei euch kundgetan! Vernehmet meine Worte!',
        15: 'Die da sind nicht betrunken, wie ihr meint; es ist ja erst die dritte Stunde des Tages.',
        16: 'Vielmehr erfüllt sich hier, was der Prophet Joel vorhergesagt hat:',
        17: "'Ich werde in den letzten Tagen,' so spricht Gott, 'von meinem Geist über alles Fleisch ausgießen. Da werden eure Söhne und eure Töchter prophezeien; eure Jünglinge werden Gesichte schauen und eure Greise Traumgesichte haben.",
        18: 'Sogar über meine Sklaven und meine Sklavinnen will ich in jenen Tagen von meinem Geist ausgießen, und sie werden prophezeien.',
        19: 'Ich werde Wunder tun am Himmel droben, und auf der Erde unten Zeichen: Blut, Feuer, Qualm und Rauch.',
        20: 'Die Sonne wird sich in Finsternis wandeln, der Mond in Blut, bevor der große und erhabene Tag des Herrn kommt.',
        21: "Doch wer den Namen des Herrn anruft, wird gerettet werden.'",
        22: 'Ihr Männer Israels! Vernehmet diese Worte: Jesus von Nazareth, ein Mann, der von Gott für euch durch Taten voll Allmacht, durch Wunder und durch Zeichen beglaubigt ward, die Gott - das wißt ihr ja selbst - durch ihn mitten unter euch vollbracht hat, ihn,',
        23: 'der durch Gottes festgesetzten Ratschluß und Vorherwissen ausgeliefert ward, ihn habt ihr durch die Hände der Gesetzeslosen ans Kreuz geschlagen und getötet.',
        24: 'Gott aber hat die Wehen des Todes gelöst und ihn auferweckt; wie es ja auch nicht möglich war, daß der Tod über ihn die Macht behielt.',
        25: "Sagt doch schon David mit Bezug auf ihn: 'Allzeit schaue ich den Herrn vor mir; er steht zu meiner Rechten, auf daß ich nicht wanke.",
        26: 'Darum frohlockte laut mein Herz, und meine Zunge jubelte, und auch mein Fleisch wird voller Hoffnung ruhen;',
        27: 'denn du wirst meine Seele nicht dem Totenreich preisgeben und deinem Heiligen nicht die Verwesung zu schauen geben.',
        28: 'Du lehrst mich des Lebens Wege, erfüllst mich vor deinem Angesicht mit Wonne.\'"',
        29: '"Meine Brüder! Ganz offen darf ich über unseren Patriarchen David vor euch reden; er starb und ward begraben; sein Grabmal ist hier bei uns bis auf den heutigen Tag.',
        30: 'Er war ja ein Prophet und hat gewußt, daß Gott mit einem Eid ihm verheißen hatte, er werde einstens einen seiner Nachkommen auf seinen Thron erheben das heißt, daß Christus leiblich auferstehen werde.',
        31: 'So schaut und kündet er zum voraus Christi Auferstehung; dieser wird nicht im Totenreich verbleiben noch wird sein Fleisch Verwesung erfahren.',
        32: 'Diesen Jesus hat Gott auferweckt; dessen sind wir alle Zeugen.',
        33: 'Er ward erhöht durch Gottes Rechte, empfing vom Vater den verheißenen Heiligen Geist, den er ausgegossen hat, wie ihr jetzt seht und hört.',
        34: "Denn nicht David stieg zum Himmel auf, und doch sagt er: 'Es sprach der Herr zu meinem Herrn; setze dich zu meiner Rechten,",
        35: "bis ich deine Feinde zum Schemel deiner Füße mache.'",
        36: 'So soll denn das ganze Haus Israel mit aller Sicherheit erkennen, daß Gott gerade diesen Jesus, den ihr gekreuzigt habt, zum Herrn und Christus gemacht hat.',
        37: 'Als sie dies hörten, ging ein Stich ihnen durchs Herz, und sie sprachen zu Petrus und den anderen Aposteln: "Liebe Brüder, was sollen wir tun?"',
        38: 'Petrus sprach zu ihnen: "Bekehret euch! Jeder von euch lasse sich taufen auf den Namen Jesu Christi für die Vergebung eurer Sünden, damit ihr die Gabe des Heiligen Geistes empfanget.',
        39: 'Die Verheißung gilt euch und euren Kindern und all denen, die noch ferne sind, so viele auch der Herr unser Gott berufen wird."',
        40: 'Noch mit vielen weiteren Worten beschwor und ermahnte er sie: "Laßt euch erretten von diesem ganz verdorbenen Geschlecht."',
        41: 'Die nun sein Wort bereitwillig annahmen, wurden getauft, und an jenem Tage kamen gegen dreitausend Seelen hinzu.',
        42: 'Sie hielten fest an der Lehre der Apostel und an der Gemeinschaft, am Brotbrechen und am Gebet.',
        43: 'Furcht ergriff alle Herzen; denn viele Wunder und Zeichen geschahen durch die Apostel in Jerusalem, so daß große Furcht auf allen lag.',
        44: 'Alle Gläubigen hielten zusammen und betrachteten all ihre Habe als gemeinsames Eigentum;',
        45: 'auch verkauften sie dann und wann ihr Hab und Gut und verteilten den Erlös an alle, je nach Bedürfnis.',
        46: 'Täglich verharrten sie einmütig im Tempel, brachen in den einzelnen Häusern das Brot und genossen ihre Speisen in stolzer Freudigkeit und Einfalt des Herzens;',
        47: 'Sie priesen Gott und waren beim ganzen Volk beliebt. Täglich führte der Herr ihnen neue zu, die gerettet werden sollten.',
    },
    3: {
        1: 'Petrus und Johannes gingen zum Tempel hinauf; es war um die neunte Gebetsstunde.',
        2: 'Da trug man eben einen Mann daher, der von Geburt an lahm war. Tag für Tag setzte man ihn an das sogenannte "Schöne Tor" des Tempels, damit er sich von den Tempelbesuchern ein Almosen erbetteln solle.',
        3: 'Als er Petrus und Johannes sah, wie sie eben in den Tempel hineingehen wollten, bat er sie um ein Almosen.',
        4: 'Petrus und zugleich Johannes sah ihn scharf an und sprach: "Schau auf uns her!"',
        5: 'Er sah gespannt auf sie in der Meinung, etwas von ihnen zu bekommen.',
        6: 'Petrus aber sprach: "Silber und Gold habe ich nicht, doch was ich habe, gebe ich dir: Im Namen Jesu Christi von Nazareth steh auf und geh umher!"',
        7: 'Damit faßte er ihn an seiner rechten Hand und richtete ihn auf. Sogleich kam Kraft in seine Füße und Knöchel;',
        8: 'er sprang auf und konnte stehen; er wandelte umher und begab sich mit ihnen in den Tempel, lief, sprang umher und lobte Gott.',
        9: 'Alles Volk sah, wie er umherging und Gott lobte.',
        10: 'Sie erkannten ihn als denselben, der des Almosens halber am "Schönen Tor" des Tempels gesessen hatte, und wurden voll von Staunen und Verwunderung über den Vorfall.',
        11: 'Er hielt sich zu Petrus und Johannes, und alles Volk lief außer sich vor Staunen zu ihnen in die sogenannte Halle Salomons.',
        12: 'Als Petrus dies sah, sprach er zum Volke: "Ihr Männer Israels! Was wundert ihr euch über diesen hier, oder was seht ihr uns so staunend an, als hätten wir es aus eigener Kraft und Frömmigkeit soweit gebracht, daß dieser gehen kann?',
        13: 'Der Gott Abrahams, Isaaks und Jakobs, der Gott unserer Väter, hat Jesus, seinen Knecht, verherrlicht. Ihr freilich habt ihn ausgeliefert und vor Pilatus verworfen, als dieser ihn freilassen wollte.',
        14: 'Den Heiligen und Gerechten habt ihr verworfen und verlangt, man solle euch den Mörder schenken;',
        15: 'den Fürsten des Lebens aber habt ihr gemordet. Doch Gott hat ihn von den Toten erweckt; dessen sind wir Zeugen.',
        16: 'Sein Name hat jetzt diesem da, den ihr seht und kennt, auf Grund des Glaubens an diesen seinen Namen Kraft verliehen. Und dieser Glaube, der durch ihn zustande kommt, gab ihm auch die volle Gesundheit zurück, wie ihr jetzt alle seht.',
        17: 'Wohlan denn, meine Brüder, ich weiß, ihr habt es nur aus Unwissenheit getan, so wie auch eure Obern.',
        18: 'Gott aber hat auf diese Art erfüllt, was er durch den Mund aller Propheten vorherverkündet hat, daß sein Christus werde leiden müssen.',
        19: 'So tut denn Buße und bekehret euch, damit eure Sünden nachgelassen werden.',
        20: 'Dann werden Zeiten der Erquickung durch die Gnade des Herrn kommen, er wird Christus Jesus senden, der für euch vorherbestimmt ist.',
        21: 'Ihn mußte zwar der Himmel erst aufnehmen, bis daß die Zeit gekommen wäre, da alles soll wiederhergestellt werden, wovon Gott durch den Mund seiner uralten heiligen Propheten geredet hat.',
        22: "Moses ist es, der da sagte: 'Einen Propheten wird für euch der Herr und unser Gott erwecken aus der Mitte eurer Brüder wie mich. Hört auf ihn in allem, was immer er euch sagen wird.",
        23: "Wer aber nicht auf den Propheten hört, der soll aus dem Volke ausgerottet werden.'",
        24: 'Auch alle anderen Propheten von Samuel an und später, so viele ihrer auch geredet haben, haben eben diese Tage verkündet.',
        25: "Ihr seid die Söhne der Propheten, und ihr gehört dem Bund an, den Gott mit euren Vätern einst geschlossen hat, als er zu Abraham sprach: 'Alle Geschlechter der Erde sollen sich in deinem Stamme segnen.'",
        26: 'Für euch vor allem hat Gott seinen Knecht auferweckt und gesandt, daß er euch segne unter der Bedingung, daß sich ein jeder von seiner Schlechtigkeit bekehre."',
    },
    4: {
        1: 'Während sie noch so zum Volke redeten, traten die Priester, der Hauptmann der Tempelwache und die Sadduzäer auf sie zu.',
        2: 'Sie waren unwillig, weil sie das Volk lehrten und unter Hinweis auf Jesus die Auferstehung der Toten verkündeten.',
        3: 'Sie legten Hand an sie und gaben sie in Gewahrsam bis zum anderen Tage; denn es war bereits Abend.',
        4: 'Viele aber von denen, die die Rede gehört hatten, wurden gläubig, und so stieg die Zahl der Männer auf ungefähr fünftausend.',
        5: 'Am folgenden Morgen versammelten sich die Obersten, die Ältesten und die Schriftgelehrten in Jerusalem,',
        6: 'auch der Hohepriester Annas, Kaiphas, Johannes und Alexander und wer sonst noch zum Priesteradel gehörte.',
        7: 'Man ließ Petrus und Johannes vorführen und fragte sie: "Mit welcher Vollmacht und in wessen Namen habt ihr dies getan?"',
        8: 'Da sprach Petrus, erfüllt vom Heiligen Geiste, zu ihnen: "Oberste des Volkes und Älteste höret',
        9: 'Wenn wir heute wegen einer Wohltat, die wir einem kranken Mann erwiesen haben, jetzt darüber vernommen werden, durch wen er gesund geworden sei,',
        10: 'so sei euch allen und dem ganzen Volke Israel kund: Im Namen Jesu Christi, des Nazareners, den ihr gekreuzigt habt, den aber Gott von den Toten erweckt hat, in ihm steht dieser hier gesund vor euren Augen.',
        11: 'Er ist der Stein, der von euch, den Bauleuten, verworfen ward, jedoch zum Schlußstein geworden ist.',
        12: 'In keinem anderen gibt es Rettung; denn es gibt keinen anderen Namen unter dem Himmel, der uns Menschen gegeben wäre, in dem wir selig werden müssen."',
        13: 'Als sie den Freimut des Petrus und Johannes gewahrten und merkten, daß es ungelehrte und ungebildete Leute waren, verwundenen sie sich. Auch stellten sie fest, daß sie ehemalige Jünger Jesu seien.',
        14: 'Da sie zugleich den Mann, der geheilt war, bei ihnen stehen sahen, wußten sie nichts zu entgegnen.',
        15: 'Man ließ sie aus dem Sitzungssaal abführen, und sie beratschlagten miteinander',
        16: 'und sagten: "Was sollen wir mit diesen Menschen machen? Denn daß ein offenkundiges Wunder durch sie geschehen ist, ist allen in Jerusalem bekannt; wir können es nicht leugnen.',
        17: 'Doch damit die Sache sich nicht weiter mehr im Volke verbreite, wollen wir ihnen unter Drohungen einschärfen, zu keinem Menschen mehr in diesem Namen zu reden."',
        18: 'Man rief sie wieder herein und verbot ihnen, je wieder im Namen Jesu zu reden oder zu predigen.',
        19: 'Petrus und Johannes aber erwiderten ihnen: "Ob es vor Gott berechtigt ist, mehr auf euch als auf Gott zu hören, darüber urteilt selber.',
        20: 'Unmöglich ist es uns, von dem nicht zu reden, was wir gesehen und gehört haben."',
        21: 'Jene aber drohten ihnen noch einmal und entließen sie. Denn sie fanden keinen Grund, sie zu bestrafen, schon des Volkes wegen nicht; denn alle priesen Gott ob des Geschehenen.',
        22: 'War doch der Mann, an dem dieses Wunder geschehen war, schon über vierzig Jahre alt.',
        23: 'Nach ihrer Freilassung kamen sie zu den Ihrigen und berichteten alles, was die Hohenpriester und die Ältesten zu ihnen gesagt hatten.',
        24: 'Sie vernahmen es und erhoben alle zumal ihre Stimme zu Gott und beteten. "Herr! Du hast den Himmel und die Erde, das Meer und alles, was darinnen ist, gemacht.',
        25: "Du hast durch den Heiligen Geist aus dem Munde unseres Vaters David, Deines Knechtes, gesprochen: 'Warum toben die Heiden und planen die Völker Nichtiges?",
        26: "Die Könige der Erde stehen auf, und Herrscher scharen sich zusammen, dem Herrn und seinem Gesalbten zum Trotz.'",
        27: 'Wahrhaftig, es haben sich in dieser Stadt vereinigt Herodes und Pontius Pilatus mit den Heiden und den Stämmen Israels gegen Jesus, Deinen heiligen Knecht, den Du gesalbt hast,',
        28: 'um auszuführen, was Deine Hand und was Dein Ratschluß festgesetzt hat, daß es geschehen solle.',
        29: 'Und jetzt o Herr, sieh hin auf ihre Drohungen. Verleihe Deinen Knechten, Dein Wort mit allem Freimut zu verkünden,',
        30: 'wenn Du Deine Hand ausstreckst, um zu heilen und Zeichen und Wunder zu vollbringen im Namen Deines heiligen Knechtes Jesus."',
        31: 'Während sie so beteten, erbebte der Ort, an dem sie versammelt waren, und alle wurden mit dem Heiligen Geist erfüllt und verkündeten freimütig das Wort Gottes.',
        32: 'Die Menge der Gläubigen war ein Herz und eine Seele. Niemand betrachtete etwas von seiner Habe als sein Eigentum; sie hatten alles miteinander gemeinsam.',
        33: 'Mit großer Kraft gaben die Apostel Zeugnis von der Auferstehung des Herrn Jesus Christus. Große Liebe herrschte unter ihnen allen.',
        34: 'So gab es keinen Darbenden unter ihnen; denn wer immer Grundstücke oder Häuser besaß, verkaufte sie und brachte den Erlös des Verkauften',
        35: 'und stellte ihn den Aposteln zur freien Verfügung. Einem jeden wurde davon nach Bedarf zugeteilt.',
        36: 'So besaß Joseph, der von den Aposteln den Beinamen Barnabas, das heißt "Tröster", erhalten hatte, ein Levit, aus Cypern stammend,',
        37: 'einen Acker; er verkaufte ihn, brachte das Geld und stellte es den Aposteln zur Verfügung.',
    },
    5: {
        1: 'Auch ein Mann namens Ananias verkaufte mit seinem Weibe Saphira ein Grundstück.',
        2: 'Mit Wissen seines Weibes behielt er von dem Verkaufspreis einen Teil zurück und brachte nur den anderen und stellte ihn den Aposteln zur Verfügung.',
        3: 'Da sprach Petrus: "Ananias, warum hat der Satan dir das Herz erfüllt, daß du den Heiligen Geist belogest und einen Teil des Erlöses aus deinem Acker für dich zurückbehieltest?',
        4: 'Blieb er denn nicht dein eigen, wenn du ihn nicht verkaufen wolltest, und auch, nachdem du ihn verkauft hast, hast du nicht frei verfügen können? Wie konntest du nur solcherlei Gedanken in deinem Herzen fassen? Nicht Menschen hast du angelogen, sondern Gott."',
        5: 'Als Ananias diese Worte hörte, fiel er zu Boden und war tot. Große Furcht ergriff alle, die es hörten.',
        6: 'Junge Männer standen auf, deckten ihn zu, trugen ihn hinaus und begruben ihn.',
        7: 'Es vergingen ungefähr drei Stunden, da kam auch sein Weib herein, ohne von dem Vorgefallenen etwas zu wissen.',
        8: 'Petrus sprach zu ihr: "Sage mir: Habt ihr den Acker nur um soviel verkauft?" "Ja", sagte sie, "nur um soviel."',
        9: 'Da sprach Petrus zu ihr: "Was seid ihr übereingekommen, den Geist des Herrn zu versuchen? Siehe, die Füße derer, die deinen Mann begraben haben, stehen vor der Tür, um auch dich hinauszutragen."',
        10: 'Im selben Augenblick fiel sie vor seinen Füßen nieder und war tot. Die Jünglinge kamen herein, fanden sie tot, trugen sie hinaus und begruben sie an der Seite ihres Mannes.',
        11: 'Gewaltige Furcht kam über alle, die davon hörten.',
        12: 'Durch die Hände der Apostel geschahen viele Zeichen und Wunder unter dem Volke. Einmütig versammelten sie sich alle in der Halle Salomos.',
        13: 'Von den anderen aber wagte niemand, sich zu ihnen zu gesellen; das Volk jedoch schätzte sie hoch.',
        14: 'Immer mehr wuchs die Zahl der Männer und Frauen, die den Glauben an den Herrn annahmen.',
        15: 'Man trug die Kranken sogar auf die Straße und legte sie auf Betten und Bahren, damit, wenn Petrus vorübergehe, wenigstens sein Schatten auf den einen oder anderen aus ihnen falle und sie von ihren Krankheiten befreit wurden.',
        16: 'Auch aus den umliegenden Städten strömte das Volk nach Jerusalem zusammen und brachte Kranke und von unreinen Geistern geplagte mit, und alle wurden geheilt.',
        17: 'Da erhoben sich der Hohepriester und alle seine Anhänger, nämlich die Sekte der Sadduzäer, voll Eifersucht;',
        18: 'sie ließen die Apostel festnehmen und ins Stadtgefängnis werfen.',
        19: 'Ein Engel des Herrn aber öffnete in der Nacht die Tore des Gefängnisses, führte sie heraus und sprach:',
        20: '"Gehet hin und tretet im Tempel auf und redet zu dem Volk alle Worte dieses Lebens."',
        21: 'Daraufhin gingen sie mit Tagesanbruch in den Tempel und lehrten. Nun erschienen der Hohepriester und seine Anhänger; sie beriefen den Hohen Rat, das heißt alle Ältesten der Söhne Israels. Sie schickten zum Gefängnis, um die Apostel vorführen zu lassen.',
        22: 'Die Diener gingen hin öffneten das Gefängnis, fanden sie aber nicht im Gefängnis. Sie kehrten zurück mit der Meldung:',
        23: '"Wir fanden das Gefängnis in aller Ordnung fest verschlossen, die Wachen standen an den Toren, doch als wir öffneten, fanden wir niemand mehr darin."',
        24: 'Als der Tempelhauptmann und die Oberpriester diese Kunde vernahmen, fragten sie sich ratlos, was denn daraus noch werden solle.',
        25: 'Da kam jemand mit der Meldung: "Die Männer, die ihr gefangengenommen habt, sind im Tempel und lehren dort das Volk."',
        26: 'Da begab sich der Hauptmann mit den Dienern hin und holte sie herbei; doch nicht mit Gewalt; denn sie fürchteten, sie möchten vom Volk gesteinigt werden.',
        27: 'Sie führten sie also herbei und stellten sie vor den Hohen Rat. Der Hohepriester hielt ihnen vor:',
        28: '"Wir haben euch doch streng verboten, in diesem Namen da zu lehren. Und doch habt ihr Jerusalem mit eurer Lehre angefüllt und wollt das Blut dieses Menschen auf uns bringen."',
        29: 'Petrus aber und die übrigen Apostel antworteten: "Man muß Gott mehr gehorchen als den Menschen.',
        30: 'Denn der Gott unserer Väter hat Jesus, den ihr ans Holz gehängt und gemordet habt, auferweckt.',
        31: 'Ihn hat nun Gott durch seine Rechte zum Fürsten und zum Heiland erhöht, um Israel Bekehrung und Sündennachlaß zu gewähren.',
        32: 'Und wir sind Zeugen dieser Dinge, wie auch der Heilige Geist, den Gott denen verliehen hat, die ihm gehorsam sind."',
        33: 'Bei diesen Worten gerieten sie in Wut und wollten sie töten.',
        34: 'Da erhob sich im Hohen Rat ein Pharisäer namens Gamaliel, ein beim ganzen Volke angesehener Gesetzeslehrer. Er hieß die Männer auf kurze Zeit hinausführen;',
        35: 'dann sprach er zu ihnen: "Ihr Männer Israels, seht euch wohl vor, wie ihr mit diesen Leuten verfahren wollt.',
        36: 'Vor einiger Zeit trat Theudas auf und gab vor, etwas Besonderes zu sein. Es schlossen sich ihm gegen vierhundert Leute an. Doch er wurde getötet, und alle, die sich ihm angeschlossen hatten, zersprengt und schließlich ganz vernichtet.',
        37: 'Nach ihm erhob sich in den Tagen der Schätzung der Galiläer Judas und verführte viel Volk zum Abfall. Auch dieser ging zugrunde, und alle, die ihm angehangen hatten, wurden weit zersprengt.',
        38: 'Was aber diesen Fall betrifft, so sage ich euch: Laßt ab von diesen Leuten, gebt sie frei! Denn geht dieses Vorhaben oder dieses Werk von Menschen aus, dann wird es ein Ende nehmen;',
        39: 'doch kommt es von Gott, so werdet ihr ihnen kein Ende bereiten können; ja, ihr könntet gar als Widersacher gegen Gott erfunden werden." Sie stimmten ihm bei.',
        40: 'Dann ließen sie die Apostel rufen, ließen sie geißeln und verboten ihnen, im Namen Jesu zu reden. Darauf entließen sie dieselben.',
        41: 'Sie aber gingen voll Freude vom Hohen Rat hinweg, weil sie gewürdigt worden waren, um des Namens Jesu willen Schmach zu leiden.',
        42: 'Und sie hörten nicht auf, Tag für Tag im Tempel und in den Häusern zu lehren und die frohe Botschaft von Christus Jesus zu verkünden.',
    },
    6: {
        1: 'In jenen Tagen, da die Jünger sich mehrten, entstand ein Murren der Hellenisten gegen die Hebräer, daß ihre Witwen bei der täglichen Almosenverteilung zurückgesetzt würden.',
        2: 'Da beriefen die Zwölf eine Versammlung der Jünger und erklärten: "Es geht nicht an, daß wir das Wort Gottes hintansetzen, um die Tische zu besorgen.',
        3: 'So sucht euch denn, ihr lieben Brüder, bei euch sieben Männer aus, die ein gutes Zeugnis haben und voll des Heiligen Geistes und voll Weisheit sind; die wollen wir für diese Sache bestellen.',
        4: 'Wir aber werden weiter dem Gebete sowie dem Dienste des Wortes uns widmen."',
        5: 'Der Vorschlag fand den Beifall der ganzen Versammlung. Sie wählten Stephanus, einen Mann voll Glauben und Heiligen Geistes, den Philippus, Prochorus, Nikanor, Timon, Parmenas und Nikolaus, einen Proselyten aus Antiochien.',
        6: 'Diese stellte man den Aposteln vor. Sie legten ihnen unter Gebet die Hände auf.',
        7: 'Und das Wort Gottes verbreitete sich, und die Zahl der Jünger ward in Jerusalem groß, sogar eine große Anzahl von Priestern unterwarf sich dem Glauben.',
        8: 'Stephanus, voll Liebe und Kraft, tat große Zeichen und Wunder unter dem Volke.',
        9: 'Da erhoben sich einige aus der sogenannten Synagoge der Libertiner, Cyrenäer und Alexandriner und derer aus Cilizien und Asien und stritten mit Stephanus.',
        10: 'Sie vermochten aber der Weisheit und dem Geiste, mit dem er sprach, nicht zu widerstehen.',
        11: 'Sie stifteten Männer an, die aussagen mußten: "Wir haben gehört, wie er Lästerworte gegen Moses und Gott ausstieß."',
        12: 'Sie hetzten das Volk, die Ältesten und die Schriftgelehrten auf, überfielen ihn, schleppten ihn fort und führten ihn vor den Hohen Rat.',
        13: 'Auch stellten sie falsche Zeugen auf, die aussagen mußten: "Dieser Mensch hört nicht auf, gegen die heilige Stätte und gegen das Gesetz Reden auszustoßen.',
        14: 'Haben wir ihn doch sagen hören: \'Der bekannte Jesus von Nazareth wird diesen Ort zerstören und die Bräuche ändern, die Moses uns überliefert hat.\'"',
        15: 'Alle, die im Hohen Rat saßen, richteten ihre Blicke auf ihn, und sein Antlitz erschien ihnen wie das Antlitz eines Engels.',
    },
    7: {
        1: 'Der Hohepriester aber fragte: "Verhält sich das so?"',
        2: 'Stephanus antwortete: "Meine Brüder! Väter! Höret! Der hocherhabene Gott erschien einst unserem Vater Abraham, als er noch in Mesopotamien lebte, bevor er sich in Charran niederließ,',
        3: "und sprach zu ihm: 'Zieh weg aus deinem Land und aus deiner Verwandtschaft und zieh in das Land, das ich dir zeigen werde.'",
        4: 'Da machte er sich aus dem Lande der Chaldäer auf und zog nach Charran. Nach dem Tode seines Vaters versetzte ihn Gott von dort in dieses Land, wo ihr jetzt wohnt.',
        5: 'Doch gab er ihm darin kein Erbe, nicht eines Fußes Breite, sondern er versprach ihm nur, er werde später ihm und seinem Stamm es als Besitztum geben, obwohl er damals noch kein Kind besaß.',
        6: "Also sprach nämlich Gott: 'Seine Nachkommen werden als Fremdlinge in fremdem Lande wohnen; man wird sie knechten und sie vierhundert Jahre lang hart bedrücken.",
        7: "Das Volk jedoch, dem sie als Knechte dienen, werde ich richten', so sprach Gott. 'Doch später werden sie von dannen ziehen und mir an diesem Orte dienen.'",
        8: 'Dann gab er ihnen das Bundeszeichen der Beschneidung. Kraft desselben zeugte er den Isaak und beschnitt ihn am achten Tage. Isaak zeugte weiterhin den Jakob, und dieser die zwölf Patriarchen.',
        9: 'Die Patriarchen waren eifersüchtig gegen Joseph und verkauften ihn nach Ägypten. Indes war Gott mit ihm.',
        10: 'Er rettete ihn aus allen seinen Drangsalen, und er verlieh ihm Gunst und Weisheit vor Pharao, dem König von Ägypten. Dieser machte ihn zum Herrn Ägyptens und seines ganzen Hauses.',
        11: 'Doch eine Hungersnot kam über ganz Ägypten und Kanaan; groß war das Elend, und unsere Väter konnten keine Lebensmittel finden.',
        12: 'Da hörte Jakob, daß es in Ägypten noch Getreide gebe; er sandte unsere Väter ein erstesmal dorthin.',
        13: 'Beim zweitenmal gab sich dann Joseph seinen Brüdern zu erkennen, und so ward dem Pharao die Abstammung des Joseph bekannt.',
        14: 'Hierauf ließ Joseph seinen Vater Jakob und alle Verwandten kommen; es waren fünfundsiebzig Seelen.',
        15: 'So zog Jakob nach Ägypten, wo er starb, er und unsere Väter.',
        16: 'Man brachte sie nach Sichem; sie wurden in dem Grabe beigesetzt, das Abraham einst um eine Summe Geldes von den Söhnen Hemors in Sichem gekauft hatte.',
        17: 'Wie nun die Zeit für die Verheißung nahte, die Gott dem Abraham zugesagt hatte, da mehrte sich das Volk in Ägypten und wurde zahlreich,',
        18: 'bis in Ägypten ein anderer König zur Herrschaft kam, der nichts von Joseph wußte.',
        19: 'Und er verfuhr mit unserem Geschlechte hinterlistig: er bedrückte unsere Väter, die ihre Kinder aussetzen mußten, damit sie nicht am Leben blieben.',
        20: 'In dieser Zeit kam Moses auf die Weit: er war Gott wohlgefällig. Drei Monate hindurch ward er im Vaterhause auferzogen;',
        21: 'dann setzte man ihn aus. Die Tochter Pharaos nahm ihn indessen an sich und zog ihn für sich auf als den eigenen Sohn.',
        22: 'Und Moses ward in aller Weisheit der Ägypter unterrichtet; mächtig in Wort und Tat.',
        23: 'Als er vierzig Jahre alt war, kam ihm das Verlangen, sich nach den Israeliten, seinen Brüdern, umzusehen.',
        24: 'Da sah er, wie irgendeinem Unrecht getan ward. Er setzte sich zur Wehr und schaffte dem Mißhandelten sein Recht und schlug den Ägypter tot.',
        25: 'Er meinte, seine Brüder würden wohl verstehen, daß Gott ihnen Rettung durch seine Hand verschaffen wolle; doch sie verstanden es nicht.',
        26: "Des anderen Tags kam er zu ihnen, als sie gerade miteinander stritten. Er wollte zwischen ihnen Frieden stiften mit den Worten: 'Ihr seid doch Brüder, Männer! Warum tut ihr einander Unrecht an?'",
        27: "Doch der, der seinem Nächsten unrecht tat, stieß ihn zurück und sagte: 'Wer hat denn dich zum Herrn und Richter über uns gemacht?",
        28: "Willst du etwa mich töten, so wie du gestern den Ägypter totgeschlagen hast?'",
        29: 'Auf diese Worte hin brachte Moses sich in Sicherheit und lebte im Lande Madian als Fremdling, wo er Vater von zwei Söhnen wurde.',
        30: 'Vierzig Jahre waren schon vorüber, da erschien ihm in der Wüste bei dem Berge Sinai ein Engel in der Flamme eines brennenden Dornbusches.',
        31: 'Voll Verwunderung sah Moses die Erscheinung. Als er hinzutrat, um sie zu betrachten, erging die Stimme des Herrn:',
        32: "'Ich bin der Gott deiner Väter, der Gott Abrahams, Isaaks und Jakobs.' Moses zitterte und wagte nicht, dorthin zu schauen.",
        33: "Und also sprach der Herr zu ihm: 'Ziehe deine Schuhe aus! Der Ort, auf dem du stehst, ist heiliges Land.",
        34: "Ich habe die Bedrückung meines Volkes in Ägypten gesehen und ihr Seufzen gehört; ich bin herabgekommen, damit ich es befreie. So komm denn, ich will dich nach Ägypten senden.'",
        35: "Denselben Moses, den sie verworfen hatten, indem sie sprachen: 'Wer hat denn dich zum Herrn und Richter eingesetzt?', den hat Gott als Herrn und Befreier gesandt unter dem Schutz eines Engels, der ihm im Dornbusch erschienen war.",
        36: 'Und dieser führte sie heraus, vollbrachte Wunder und Zeichen im Lande Ägypten, im Roten Meer und in der Wüste, vierzig Jahre lang.',
        37: "Es ist derselbe Moses, der den Söhnen Israels gesagt hatte: 'Einen Propheten wie mich wird Gott euch erwecken aus der Mitte eurer Brüder.'",
        38: 'Er ist es auch, der bei der Gemeinde in der Wüste mit dem Engel verkehrte, der auf dem Berge Sinai mit ihm und mit unseren Vätern redete, und er empfing die Worte des Lebens, um sie euch mitzuteilen.',
        39: 'Doch unsere Väter wollten ihm nicht gehorsam sein; sie lehnten ihn vielmehr ab und wandten sich in ihren Herzen wieder Ägypten zu.',
        40: "So sprachen sie zu Aaron: 'Verschaffe uns Götter, die vor uns herziehen; wir wissen nicht, was aus dem Moses da geworden ist, der uns aus Ägypten herausgeführt hat.'",
        41: 'Sie machten sich in jenen Tagen ein Kalb, brachten diesem Götzenbild Opfer dar und ergötzten sich an dem Gebilde ihrer Hände.',
        42: "Da wandte Gott sich von ihnen ab und ließ sie dem Himmelsheer dienen, wie es geschrieben steht im Buche der Propheten. 'Habt ihr mir etwa Schlachttiere und Opfer dargebracht die vierzig Jahre in der Wüste, Haus Israel?",
        43: "O nein, das Zelt des Moloch und das Sternbild eures Gottes Rempham habt ihr herumgeführt, die Bilder, die ihr selbst verfertigt habt, um sie anzubeten. Ich werde euch noch über Babylon hinaus verbannen.'",
        44: "Unsere Väter hatten in der Wüste das Bundeszelt, wie der es angeordnet hatte, der zu Moses sprach: 'Er soll es machen nach dem Vorbilde, das er gesehen hat.'",
        45: 'Und dieses übernahmen unsere Väter und brachten es mit sich, als sie dann unter Josue das Land der Heiden zum Besitz erhielten, die Gott vor unseren Vätern hernach vertrieb. So blieb es bis auf Davids Zeit.',
        46: 'Dieser war Gott wohlgefällig und bat, ob er für den Gott Jakobs nicht eine Wohnung machen dürfe.',
        47: 'Jedoch erst Salomo erbaute ihm ein Haus.',
        48: 'Allein der Allerhöchste wohnt nicht in Stätten, die von Menschenhand gemacht sind. Sagt doch schon der Prophet:',
        49: "'Der Himmel ist mein Thron, die Erde der Schemel meiner Füße. Was für ein Haus wollt ihr mir bauen', spricht der Herr, 'oder wo ist der Ort, an dem ich ständig wohnen kann?",
        50: "Hat denn nicht meine Hand all dies geschaffen?'",
        51: 'O ihr Halsstarrigen und Unbeschnittenen an Herz und Ohren! Ihr widerstrebt allzeit dem Heiligen Geiste, wie eure Väter, so auch ihr.',
        52: 'Gibt es einen Propheten, den eure Väter nicht verfolgt haben? Sie haben die ermordet, die das Kommen des Gerechten vorherverkündigt haben; ihr selbst seid nun seine Verräter und Mörder geworden,',
        53: 'ihr, die ihr das Gesetz auf Anordnung von Engeln zwar erhalten, aber nicht gehalten habt."',
        54: 'Bei diesen Worten ergrimmten sie in ihrem Innersten und knirschten mit den Zähnen gegen ihn.',
        55: 'Stephanus aber, voll des Heiligen Geistes, blickte zum Himmel empor und sah die Herrlichkeit Gottes und Jesus stehend zur Rechten Gottes',
        56: 'und rief aus: "O schaut! Ich sehe die Himmel offen und den Menschensohn zur Rechten Gottes stehen."',
        57: 'Da erhoben sie ein wüstes Geschrei und hielten sich die Ohren zu. Alle miteinander stürzten sie auf ihn los,',
        58: 'stießen ihn zur Stadt hinaus und steinigten ihn. Die Zeugen gaben ihre Kleider einem jungen Manne namens Saul in Verwahrung.',
        59: 'So steinigten sie den Stephanus. Er betete: "Herr Jesus, nimm meinen Geist auf!"',
        60: 'Dann sank er in die Knie und rief mit lauter Stimme: "Herr, rechne ihnen diese Sünde nicht an!" Damit entschlief er.',
    },
    8: {
        1: 'Saul aber war mit seiner Ermordung einverstanden. Noch am selben Tage brach über die Kirche in Jerusalem eine erbitterte Verfolgung herein. Alle, mit Ausnahme der Apostel, zerstreuten sich in die Gegenden von Judäa und Samaria.',
        2: 'Den Stephanus aber bestatteten gottesfürchtige Männer und hielten eine große Totenklage um ihn.',
        3: 'Saul hingegen wütete furchtbar gegen die Kirche; er drang in die Häuser ein, schleppte Männer und Frauen fort und warf sie ins Gefängnis.',
        4: 'Die Versprengten zogen umher und verkündeten das Wort Gottes.',
        5: 'Philippus kam in die Stadt Samaria und verkündete dort Christus.',
        6: 'Einmütig horchte die Volksmenge aufmerksam auf das, was Philippus predigte, und sah die Zeichen, die er wirkte.',
        7: 'Denn von vielen, die unreine Geister hatten, fuhren diese mit lautem Geschrei aus;',
        8: 'auch viele Lahme und Krüppel wurden geheilt.',
        9: 'Es herrschte deshalb eine große Freude in jener Stadt. Ein Mann namens Simon lebte schon seit geraumer Zeit in jener Stadt. Er trieb Zauberei und betörte die Bewohner von Samaria, indem er sich für etwas Höheres ausgab.',
        10: 'Alle, klein und groß, hielten zu ihm; sie sagten: "Er ist die Kraft Gottes, die \'die Große\' heißt."',
        11: 'Sie hielten aber nur deswegen zu ihm, weil er sie längere Zeit mit seiner Zauberei betört hatte.',
        12: 'Als sie aber dem Philippus, der ihnen die frohe Botschaft vom Reiche Gottes und vom Namen Jesu Christi verkündet hatte, glaubten, ließen sich Männer und Frauen taufen.',
        13: 'Simon selber glaubte ebenfalls, ließ sich taufen und schloß sich dem Philippus an. Als er sah, welch große Zeichen und Wunder geschahen, kam er ganz außer sich.',
        14: 'Als aber die Apostel in Jerusalem hörten, daß Samaria das Wort Gottes angenommen habe, sandten sie den Petrus und Johannes dorthin.',
        15: 'Diese zogen hinab, beteten für sie, daß sie den Heiligen Geist empfangen möchten.',
        16: 'Denn er war noch auf keinen aus ihnen herabgekommen, sondern sie waren nur auf den Namen des Herrn Jesus getauft.',
        17: 'Nun legten sie ihnen die Hände auf, und sie empfingen den Heiligen Geist.',
        18: 'Als Simon sah, daß durch die Handauflegung der Apostel der Heilige Geist verliehen wurde, brachte er ihnen Geld',
        19: 'und sagte: "Gebt auch mir so große Macht, daß jeder, dem ich die Hand auflege, den Heiligen Geist empfange."',
        20: 'Petrus aber sprach zu ihm: "Dein Geld fahre samt dir ins Verderben, weil du geglaubt hast, du könntest dir die Gabe Gottes um Geld kaufen.',
        21: 'Du hast nicht teil noch Recht daran; dein Herz ist ja vor Gott nicht ehrlich.',
        22: 'Bekehre dich von dieser deiner Bosheit und bitte den Herrn, ob dir vielleicht das Sinnen deines Herzens vergeben werde.',
        23: 'Denn wie ich sehe, bist du voll bitterer Galle und liegst in den Fesseln der Bosheit."',
        24: 'Simon aber erwiderte: "Betet ihr für mich zum Herrn, damit nichts von dem, was ihr gesagt habt, mich treffe."',
        25: 'Als sie nun Zeugnis gegeben und das Wort des Herrn verkündet hatten, kehrten sie nach Jerusalem zurück und verkündeten dabei noch in vielen Ortschaften der Samariter die frohe Botschaft.',
        26: 'Ein Engel des Herrn aber gab Philippus den Auftrag: "Mache dich auf und geh um die Mittagszeit auf die Straße, die von Jerusalem nach Gaza führt; sie ist ganz unbelebt."',
        27: 'Er machte sich auf und ging hin. Ein Äthiopier, ein Eunuch und Würdenträger der Königin Kandake von Äthiopien, ihr oberster Schatzmeister, war nach Jerusalem gekommen, um anzubeten.',
        28: 'Er befand sich auf der Heimreise und las auf seinem Wagen den Propheten Isaias.',
        29: 'Es sprach aber der Geist zu Philippus: "Tritt hin und halte dich bei diesem Wagen!"',
        30: 'Philippus lief hin und hörte ihn den Propheten Isaias lesen. Er sprach zu ihm: "Verstehst du, was du liesest?"',
        31: 'Er erwiderte: "Wie sollte ich auch, wenn mich niemand anleitet?" Und er bat den Philippus, einzusteigen und sich neben ihn zu setzen.',
        32: 'Die Schriftstelle, die er gerade las, war folgende: "Wie ein Schaf ward er zur Schlachtbank geführt; wie ein Lamm, das vor dem, der es schert, verstummt, so tut auch er den Mund nicht auf.',
        33: 'Um seiner Demut willen ward das Gericht über ihn aufgehoben. Wer wird sein Geschlecht beschreiben? Denn weggenommen von der Erde wird sein Leben."',
        34: 'Der Eunuch wandte sich an Philippus und fragte: "Bitte, von wem sagt dies der Prophet? Von sich oder von irgendeinem anderen?"',
        35: 'Da öffnete Philippus seinen Mund, und, ausgehend von dieser Schriftstelle, verkündigte er ihm die frohe Botschaft von Jesus.',
        36: 'Während sie nun des Weges dahinzogen, kamen sie an ein Wasser. Der Eunuch sprach: "Siehe, hier ist Wasser, was hindert, daß ich getauft werde?"',
        37: 'Philippus sprach: "Wenn du aus ganzem Herzen glaubst, so kann es geschehen." Er antwortete und sprach: "Ich glaube, daß Jesus Christus der Sohn Gottes ist."',
        38: 'Er ließ den Wagen halten, und beide stiegen zum Wasser hinab, Philippus und der Eunuch. Dort taufte er ihn.',
        39: 'Als sie aus dem Wasser herausgestiegen waren, da entrückte der Geist des Herrn den Philippus, und der Eunuch sah ihn nicht mehr. Voll Freude zog er seines Weges weiter.',
        40: 'Philippus aber fand sich in Azot wieder. Er zog umher und verkündete in allen Städten bis nach Cäsarea hin die frohe Botschaft.',
    },
    9: {
        1: 'Noch immer brannte Saul von Wut und Mordgier gegen die Jünger des Herrn. Er ging zum Hohenpriester',
        2: 'und erbat sich von ihm Schreiben an die Synagogen in Damaskus. Er wollte etwaige Anhänger dieser Lehre, Männer und Weiber, gefesselt nach Jerusalem bringen.',
        3: 'So machte er sich auf den Weg und kam in die Nähe von Damaskus. Da umstrahlte ihn plötzlich ein Licht vom Himmel.',
        4: 'Er stürzte zu Boden und vernahm eine Stimme, die ihm zurief: "Saul, Saul, warum verfolgst du mich?"',
        5: '"Wer bist du, Herr?" so fragte er. "Ich bin Jesus, den du verfolgst", sprach er "es wird dir schwer sein, gegen den Stachel auszuschlagen".',
        6: 'Zitternd und bebend fragte er: "Herr, was willst du, daß ich tun soll?" "Steh auf; geh in die Stadt! Dort wird man dir sagen, was du tun sollst."',
        7: 'Die Männer, die mit ihm gekommen waren, standen sprachlos da; denn obwohl sie die Stimme hörten, konnten sie doch niemand sehen.',
        8: 'Saul erhob sich vom Boden. Als er die Augen aufschlug, konnte er nicht sehen. Da nahmen sie ihn bei der Hand und führten ihn nach Damaskus hinein.',
        9: 'Drei Tage lang war er blind und aß und trank nicht.',
        10: 'In Damaskus lebte ein Jünger namens Ananias. Zu diesem sprach der Herr in einem Gesichte: "Ananias!" Er antwortete: "Hier bin ich, Herr!"',
        11: 'Und der Herr gebot ihm: "Mache dich auf, geh in die Straße, die die \'Gerade\' heißt, und frage im Hause des Judas nach einem Manne namens Saul aus Tarsus. Siehe, er betet!"',
        12: 'In einem Gesichte sah Saul einen Mann namens Ananias eintreten und ihm die Hände auflegen, damit er wieder sehend würde.',
        13: 'Ananias antwortete: "O Herr, von diesem Manne habe ich von vielen Seiten schon gehört, wieviel Böses er deinen Heiligen zu Jerusalem angetan hat.',
        14: 'Und auch hier hat er die Vollmacht von den Oberpriestern, alle zu fesseln, die deinen Namen anrufen."',
        15: 'Doch der Herr erwiderte ihm: "Geh nur hin! Denn dieser ist für mich ein auserwähltes Werkzeug, um meinen Namen vor Heiden, Könige und die Kinder Israels zu tragen.',
        16: 'Ich will ihm zugleich zeigen, wieviel er um meines Namens willen leiden muß."',
        17: 'Ananias machte sich auf und ging in das Haus. Er legte ihm die Hände auf und sprach: "Bruder Saul, der Herr hat mich gesandt, Jesus, der dir auf dem Wege, den du kamst, erschienen ist, damit du wieder sehend und voll des Heiligen Geistes werdest."',
        18: 'Sofort fiel es ihm wie Schuppen von den Augen, und er konnte wieder sehen. Er stand auf und wurde getauft.',
        19: 'Dann nahm er Nahrung zu sich und erholte sich wieder. Er blieb noch einige Tage bei den Jüngern in Damaskus',
        20: 'und predigte sofort in den Synagogen, daß Jesus der Sohn Gottes ist.',
        21: 'Alle, die es hörten, wunderten sich und sprachen: "Ist das nicht derselbe, der in Jerusalem die zugrunde richtete, die diesen Namen anriefen? Kam er nicht eben deshalb auch hierher, um sie gefesselt vor die Oberpriester zu schleppen?"',
        22: 'Saul aber trat immer wirksamer auf und brachte die Juden in Damaskus in Verwirrung durch den Nachweis: "Er ist der Christus."',
        23: 'Nach einiger Zeit faßten die Juden den Plan, ihn umzubringen.',
        24: 'Ihr Anschlag wurde jedoch dem Saul bekannt. Sie bewachten aber Tag und Nacht die Tore, um ihn ermorden zu können.',
        25: 'Seine Jünger aber ließen ihn bei Nacht in einem Korb über die Mauer hinab.',
        26: 'Er kam nach Jerusalem. Dort suchte er sich den Jüngern anzuschließen; alle aber hatten Furcht vor ihm und konnten nicht glauben, daß er ein Jünger sei.',
        27: 'Barnabas aber nahm sich seiner an und führte ihn zu den Aposteln. Er erzählte ihnen, wie er auf dem Wege den Herrn gesehen, wie er mit ihm geredet und wie er in Damaskus freimütig im Namen Jesu gepredigt habe.',
        28: 'So ging er denn bei ihnen in Jerusalem ein und aus und predigte freimütig im Namen des Herrn.',
        29: 'Er redete und stritt auch mit den Hellenisten. Diese aber trachteten danach, ihn zu töten.',
        30: 'Das erfuhren die Brüder, und sie geleiteten ihn hinab nach Cäsarea und entließen ihn nach Tarsus.',
        31: 'Die Kirche hatte jetzt Frieden in ganz Judäa, Galiläa und Samaria. Sie baute sich auf und wandelte in der Furcht des Herrn, sie mehrte sich durch den Trost des Heiligen Geistes.',
        32: 'Nun geschah es, daß Petrus auf einer Rundreise bei allen auch zu den Heiligen kam, die in Lydda wohnten.',
        33: 'Dort traf er einen Mann namens Äneas. Schon seit acht Jahren lag er zu Bette; denn er war gelähmt.',
        34: 'Petrus sprach zu ihm: "Äneas, Jesus Christus heilt dich! Steh auf und mach dir selbst dein Bett!" Und sofort stand er auf.',
        35: 'Alle Bewohner von Lydda und der Saronebene sahen ihn und bekehrten sich zum Herrn.',
        36: 'In Joppe lebte eine Jüngerin namens Tabitha, das heißt Dorkas. Sie war reich an guten Werken und gab viel Almosen.',
        37: 'Eben damals geschah es nun, daß sie krank wurde und starb. Man wusch sie und bahrte sie im Obergemach auf.',
        38: 'Da Lydda nahe bei Joppe liegt und die Jünger erfahren hatten, daß sich Petrus dort aufhalte, sandten sie zwei Männer zu ihm mit der Bitte: "Säume nicht und komm zu uns herüber!"',
        39: 'Petrus machte sich auf und ging mit ihnen. Als er angekommen war, führte man ihn in das Obergemach. Alle Witwen standen um ihn herum und zeigten ihm unter Tränen die Unter- und Oberkleider, die Dorkas gemacht hatte, da sie noch unter ihnen weilte.',
        40: 'Petrus aber wies sie alle hinaus, kniete nieder und betete. Dann wandte er sich zu der Leiche und sprach: "Tabitha, steh auf!" Sie öffnete ihre Augen, und, als sie den Petrus erblickte, setzte sie sich aufrecht hin.',
        41: 'Er reichte ihr die Hand und half ihr auf. Dann rief er die Heiligen und die Witwen herein und stellte sie ihnen lebend vor.',
        42: 'Dies ward in ganz Joppe bekannt, und viele glaubten an den Herrn.',
        43: 'Er blieb dann noch geraume Zeit in Joppe bei einem Gerber namens Simon.',
    },
    10: {
        1: 'In Cäsarea lebte ein Mann namens Kornelius, Hauptmann in der so genannten Italischen Kohorte.',
        2: 'Er war samt seinem ganzen Hause fromm und gottesfürchtig, gab dem Volke reichlich Almosen und betete unablässig zu Gott.',
        3: 'Es war um die neunte Tagesstunde, da sah er ganz deutlich in einem Gesichte, wie ein Engel Gottes zu ihm hereinkam und zu ihm sprach: "Kornelius!"',
        4: 'Er aber schaute ihn starr an und fragte voll Furcht: "Was, o Herr?" Er antwortete ihm: "Deine Gebete und deine Almosen sind emporgestiegen zu Gott als Gedächtnisopfer.',
        5: 'Doch jetzt sende Männer nach Joppe und laß den Simon holen, der auch Petrus heißt.',
        6: 'Er ist zu Gast bei einem Gerber namens Simon, der am Meer ein Haus besitzt" Der wird dir sagen, was du tun sollst.',
        7: 'Der Engel, der mit ihm geredet hatte, verschwand. Er rief zwei seiner Sklaven und einen gottesfürchtigen Soldaten aus seiner ständigen Umgebung,',
        8: 'setzte ihnen alles auseinander und schickte sie nach Joppe.',
        9: 'Am anderen Tag, während jene noch unterwegs waren und sich der Stadt näherten, stieg Petrus auf das Dach, um zu beten. Es war um die sechste Stunde.',
        10: 'Er war hungrig und wünschte zu essen. Während man zurichtete, kam über ihn eine Verzückung:',
        11: 'Er schaute den Himmel offen und ein Behältnis wie ein großes Linnentuch herabkommen, das an den vier Enden auf die Erde herabgelassen wurde.',
        12: 'In ihm befanden sich alle vierfüßigen und kriechenden Tiere der Erde und Vögel des Himmels.',
        13: 'Eine Stimme rief ihm zu: "Steh auf, Petrus, schlachte und iß!"',
        14: 'Petrus erwiderte: "Nein, Herr! Noch nie habe ich etwas Gemeines und Unreines gegessen."',
        15: 'Zum zweitenmal rief es ihm zu: "Was Gott gereinigt hat, sollst du nicht gemein heißen."',
        16: 'Das geschah dreimal. Gleich darauf wurde das Behältnis wieder in den Himmel emporgehoben',
        17: 'Während Petrus noch überlegte, was das Gesicht, das er gesehen hatte, zu bedeuten habe, standen die Leute, die Kornelius abgesandt und die sich zum Hause des Simon bereits durchgefragt hatten, am Tore.',
        18: 'Sie riefen und fragten, ob hier ein Simon mit dem Beinamen Petrus wohne.',
        19: 'Petrus dachte immer noch über das Gesicht nach. Da sprach der Geist zu ihm: "Drei Männer suchen dich.',
        20: 'Steh auf und geh hinab und zieh mit ihnen ohne irgendein Bedenken; denn ich habe sie gesandt."',
        21: 'Da ging Petrus zu den Leuten hinunter und sprach zu ihnen: "Ich bin es, den ihr suchet. Was führt euch hierher?"',
        22: 'Sie antworteten ihm: "Kornelius, der Hauptmann, ein rechtlicher und gottesfürchtiger Mann, der bei der ganzen jüdischen Bevölkerung in gutem Rufe steht, ward von einem heiligen Engel angewiesen, dich in sein Haus zu holen und von dir Belehrung zu empfangen."',
        23: 'Da lud er sie ein und beherbergte sie. Am folgenden Tage machte er sich auf und zog mit ihnen fort; einige der Brüder aus Joppe begleiteten ihn.',
        24: 'Am anderen Tag langte er in Cäsarea an. Kornelius erwartete sie und hatte seine Verwandten und vertrauten Freunde eingeladen.',
        25: 'Als Petrus eintrat, ging ihm Kornelius entgegen, fiel ihm zu Füßen und begrüßte ihn.',
        26: 'Petrus aber hob ihn auf und sprach: "Steh auf! Auch ich bin nur ein Mensch."',
        27: 'Im Gespräch mit ihm trat er ein und fand viele Leute versammelt.',
        28: 'Da sprach er zu ihnen: "Ihr wisset wohl, daß es einem Juden nicht erlaubt ist, mit einem Nichtjuden näher zu verkehren oder zu ihm zu gehen. Doch mir hat Gott gezeigt, daß man keinen Menschen gemein und unrein nennen darf.',
        29: 'Ich bin deshalb ohne irgendein Bedenken mitgegangen, als ihr mich rufen ließet. Ich möchte aber doch nun wissen, warum ihr mich habt rufen lassen."',
        30: 'Kornelius erwiderte: "Gerade vor vier Tagen, auf die Stunde hin, da betete ich in meinem Hause um die neunte Stunde. Und siehe, da stand ein Mann vor mir in glänzend weißem Kleide',
        31: "und sprach: 'Kornelius! Dein Gebet ist erhört und deiner Almosen ward vor Gott gedacht.",
        32: "Schick hin nach Joppe und laß Simon rufen, der auch Petrus heißt; er weilt als Gast im Hause des Gerbers Simon dicht am Meer.'",
        33: 'Und sogleich sandte ich zu dir, und du hast recht getan, daß du gekommen bist. Jetzt sind wir alle hier vor Gott versammelt, um zu hören, was dir vom Herrn aufgetragen ist."',
        34: 'Da tat Petrus seinen Mund auf und sprach: "Nunmehr begreife ich in Wahrheit, daß Gott nicht auf die Person sieht,',
        35: 'daß ihm vielmehr in jedem Volke der angenehm ist, der ihn fürchtet und Gerechtigkeit übt.',
        36: 'Das Wort hat er den Kindern Israels gesandt, indem er Frieden verkündigte durch Jesus Christus; dieser ist der Herr aller.',
        37: 'Ihr kennt die Begebenheiten, die sich im ganzen Judenland zugetragen haben: In Galiläa fing er an nach der Taufe, die Johannes verkündete;',
        38: 'ich meine Jesus von Nazareth, den Gott mit dem Heiligen Geist und mit Wunderkraft gesalbt hat, der dann umhergezogen ist, Wohltaten spendete und alle vom Teufel Besessenen geheilt hat; Gott war ja mit ihm.',
        39: 'Wir sind von all dem Zeugen, was er im Judenland und in Jerusalem gewirkt hat. Man hat ihn zwar getötet, indem man ihn ans Holz gehängt hat.',
        40: 'Gott aber hat ihn am dritten Tag auferweckt und sichtbar werden lassen,',
        41: 'zwar nicht dem ganzen Volke, doch den von Gott vorbestimmten Zeugen, uns, die wir nach seiner Auferstehung von den Toten mit ihm zusammen gesessen und getrunken haben.',
        42: 'Er hat uns aufgetragen, dem Volke zu verkünden und zu bezeugen, daß er der von Gott bestellte Richter über Lebendige und Tote ist.',
        43: 'Von ihm bezeugen alle Propheten, daß jeder, der an ihn glaubt, durch seinen Namen Nachlaß der Sünden empfangen wird."',
        44: 'Während Petrus noch so redete, kam der Heilige Geist auf alle herab, die die Predigt hörten.',
        45: 'Die Gläubigen aus der Beschneidung, die mit Petrus gekommen waren, wunderten sich, daß auch über die Heiden die Gabe des Heiligen Geistes ausgegossen wurde;',
        46: 'denn sie hörten, wie sie in Sprachen redeten und Gott lobpriesen. Da sprach Petrus:',
        47: '"Kann man das Wasser der Taufe denen versagen, die gleich uns den Heiligen Geist empfangen haben?"',
        48: 'So ließ er sie denn im Namen Jesu Christi taufen. Hierauf baten sie ihn, noch einige Tage dazubleiben.',
    },
    11: {
        1: 'Die Apostel und die Brüder in Judäa erfuhren, daß auch die Heiden das Wort Gottes angenommen hätten.',
        2: 'Als nun Petrus nach Jerusalem hinaufkam, stritten die aus dem Judentum mit ihm',
        3: 'und sagten: "Du bist bei Unbeschnittenen eingekehrt und hast mit ihnen Mahl gehalten."',
        4: 'Petrus aber hob an und setzte ihnen den ganzen Hergang der Reihe nach auseinander. Er sprach:',
        5: '"Ich war in der Stadt Joppe und wollte eben mein Gebet verrichten. Da hatte ich in der Verzückung ein Gesicht: Ein Behältnis wie ein großes Linnentuch kam herab und hing an den vier Enden aus dem Himmel her und kam gerade auf mich zu.',
        6: 'ich sah genau hin und sah die vierfüßigen Tiere der Erde und die wilden Tiere und die Kriechtiere und auch die Vögel des Himmels.',
        7: "Auch hörte ich eine Stimme, die mir zurief: 'Petrus, steh auf, schlachte und iß!'",
        8: "Doch ich erwiderte: 'Nein, Herr! Noch nie kam etwas Gemeines oder Unreines in meinen Mund.'",
        9: "Jedoch zum zweitenmal sprach die Stimme vom Himmel her: 'Was Gott gereinigt hat, darfst du nicht gemein nennen.'",
        10: 'Und das geschah ein drittes Mal. Dann wurde alles wieder in den Himmel hinaufgezogen.',
        11: 'Im selben Augenblick standen drei Männer vor dem Hause, in dem wir uns befanden; sie waren zu mir aus Cäsarea hergesandt.',
        12: 'Der Geist hieß mich mit ihnen gehen ohne irgendein Bedenken. Und mit mir reisten die sechs Brüder da; so kamen wir in das Haus des Mannes.',
        13: "Und er erzählte uns, wie er in seinem Hause den Engel habe stehen sehen, der zu ihm sprach: 'Sende hin nach Joppe und laß den Simon holen, der auch Petrus heißt.",
        14: "Und er wird Worte zu dir sprechen, kraft deren du samt deinem ganzen Hause gerettet werden wirst.'",
        15: 'Kaum hatte ich zu reden angefangen, da kam der Heilige Geist auf sie herab, wie damals auf uns.',
        16: "Und da gedachte ich des Herrenwortes, das er einstens sprach: 'Johannes hat nur mit Wasser getauft; ihr aber werdet mit dem Heiligen Geiste getauft werden.'",
        17: 'Wenn Gott nun ihnen die gleiche Gnade gab wie uns, die wir schon an den Herrn Jesus Christus glaubten, woher hätte ich mir die Macht nehmen sollen, Gott zu hindern?"',
        18: 'Als sie dies gehört hatten, gaben sie sich zufrieden; sie lobten Gott und sprachen: "Also hat Gott auch den Heiden die Sinnesänderung verliehen, die zum Leben führt."',
        19: "Durch die Verfolgung, die des Stephanus' wegen ausgebrochen war, wurden viele versprengt und kamen bis nach Phönizien, Cypern und Antiochien. Sie verkündigten aber niemand das Wort als allein den Juden.",
        20: 'Jedoch einige aus ihnen, Männer aus Cypern und der Cyrenaika, verkündeten, als sie in Antiochien angekommen waren, auch den Heiden die frohe Botschaft vom Herrn Jesus.',
        21: 'Die Hand des Herrn war mit ihnen, und eine beträchtliche Anzahl wurde gläubig und bekehrte sich zum Herrn.',
        22: 'Die Kunde davon kam zu den Ohren der Gemeinde in Jerusalem. Man entsandte den Barnabas nach Antiochien.',
        23: 'Als er ankam und die Gnade Gottes sah, freute er sich; er ermahnte alle, so wie sie es sich in ihrem Herzen vorgenommen hätten, beim Herrn zu bleiben.',
        24: 'War er doch ein trefflicher Mann, voll Heiligen Geistes und Glaubens. Es wurde auch eine große Anzahl für den Herrn hinzugewonnen.',
        25: 'Er reiste dann nach Tarsus, um den Saulus aufzusuchen;',
        26: 'er traf ihn und nahm ihn nach Antiochien mit. Dort wirkten sie noch ein ganzes Jahr in der Gemeinde zusammen und unterrichteten eine ansehnliche Menge. In Antiochien nannte man die Jünger zum erstenmal "Christen".',
        27: 'In dieser Zeit kamen von Jerusalem her Propheten nach Antiochien.',
        28: 'Einer aus ihnen, namens Agabus, stand auf und kündigte durch den Geist an, daß eine große Hungersnot über den ganzen Erdkreis kommen werde. Sie trat dann unter Claudius wirklich ein.',
        29: 'Die Jünger aber faßten den Beschluß, daß ein jeder von ihnen je nach Vermögen den Brüdern in Judäa eine Unterstützung zukommen lassen solle.',
        30: 'Dieses taten sie auch und sandten das Geld an die Presbyter durch Barnabas und Saul.',
    },
    12: {
        1: 'Um dieselbe Zeit legte der König Herodes Hand an einige Angehörige der Gemeinde, um sie zu mißhandeln.',
        2: 'Er ließ Jakobus, den Bruder des Johannes, mit dem Schwerte hinrichten.',
        3: 'Da er sah, daß dies den Juden gefiel, ließ er auch den Petrus ergreifen. Es war in den Tagen der Ungesäuerten Brote.',
        4: 'Er ließ ihn also festnehmen und ins Gefängnis werfen und durch eine vierfache Wache von je vier Soldaten bewachen. Nach Ostern wollte er ihn dann dem Volke vorführen.',
        5: 'Petrus wurde im Gefängnis bewacht, von der Gemeinde aber wurde ohne Unterlaß für ihn zu Gott gebetet.',
        6: 'In der Nacht, bevor Herodes ihn vorführen lassen wollte, schlief Petrus mit zwei Ketten gefesselt zwischen zwei Soldaten. Wachtposten vor der Türe bewachten das Gefängnis.',
        7: 'Siehe, da erschien ein Engel des Herrn, Licht erstrahlte in dem Gelaß; er stieß den Petrus in die Seite, weckte ihn und sprach: "Schnell, auf!" Da fielen ihm die Ketten von den Händen.',
        8: 'Der Engel gebot ihm weiter: "Gürte dich und ziehe deine Schuhe an!" Er tat es. Weiter sprach er: "Wirf deinen Mantel um und folge mir!"',
        9: 'Er ging hinaus und folgte ihm, wußte aber nicht, daß es Wirklichkeit war, was durch den Engel geschah; er meinte vielmehr, ein Gesicht zu schauen.',
        10: 'Sie schritten an der ersten und zweiten Wache rasch vorüber und kamen an das eiserne Tor, das in die Stadt hineinführt; dieses tat sich ihnen von selbst auf. Sie traten ein und gingen in eine gewisse Straße, und plötzlich schied der Engel von ihm.',
        11: 'Da kam Petrus, zu sich und sprach: "Jetzt weiß ich in Wahrheit, der Herr hat seinen Engel gesandt und mich aus der Hand des Herodes gerissen, und aus dem, was das Judenvolk erwartete."',
        12: 'Und als er sich das klargemacht hatte, ging er zum Hause der Maria, der Mutter des Johannes mit dem Beinamen Markus. Hier waren viele versammelt und beteten.',
        13: 'Er klopfte an die Tür des Hoftors. Eine Magd mit Namen Rhode kam herbei, um zu horchen.',
        14: 'Als sie die Stimme des Petrus erkannte, öffnete sie vor lauter Freude das Tor nicht, sondern lief hinein und meldete, Petrus Stehe vor dem Tore.',
        15: 'Die aber sagten zu ihr: "Du bist von Sinnen." Doch sie bestand fest darauf, daß es so sei. Da meinten sie: "Es ist sein Engel."',
        16: 'Petrus aber fuhr fort zu klopfen; man öffnete, sah ihn und staunte.',
        17: 'Er aber winkte ihnen mit der Hand, daß sie schweigen möchten, und erzählte ihnen dann, wie ihn der Herr aus dem Gefängnis herausgeführt habe. Er sagte noch: "Meldet dies dem Jakobus und den anderen Brüdern!" Dann ging er weg und begab sich an einen anderen Ort.',
        18: 'Als es Tag geworden war, entstand unter den Soldaten eine nicht geringe Aufregung, was aus Petrus geworden war.',
        19: 'Herodes, der ihn holen lassen wollte, aber nicht vorfand, verhörte die Wächter und ließ sie dann zur Hinrichtung abführen. Hierauf begab er sich von Judäa nach Cäsarea hinab und hielt sich dort auf.',
        20: 'Gegen die Bewohner von Tyrus und von Sidon war er sehr erzürnt. Diese erschienen nun einmütig vor ihm, und nachdem sie den königlichen Kammerherrn Blastus für sich gewonnen hatten, baten sie um Frieden; denn ihr Land bezog von dem des Königs die Lebensmittel.',
        21: 'An dem bestimmten Tage setzte sich Herodes in königlichem Gewand auf seinen Thron und hielt eine Ansprache an sie.',
        22: 'Das Volk brach in den Ruf aus: "Eines Gottes, nicht eines Menschen Stimme."',
        23: 'Auf der Stelle schlug ihn ein Engel des Herrn dafür, daß er nicht Gott die Ehre gegeben hatte. Und von Würmern zerfressen starb er.',
        24: 'Das Wort des Herrn aber breitete sich immer weiter aus.',
        25: 'Barnabas und Saul kehrten aus Jerusalem zurück, nachdem sie ihre Aufgabe erfüllt hatten; sie nahmen Johannes mit dem Beinamen Markus mit sich.',
    },
    13: {
        1: 'In der Gemeinde zu Antiochien gab es Propheten und Lehrer: Barnabas, Symeon, genannt Niger, Lucius von Cyrene, Manahen, ein Milchbruder des Vierfürsten Herodes, und Saul.',
        2: 'Während sie dem Herrn den heiligen Dienst verrichteten und fasteten, sprach der Heilige Geist: "Sondert mir den Barnabas und Saul für die Aufgabe aus, zu der ich sie berufen habe."',
        3: 'Hierauf fasteten und beteten sie, legten ihnen die Hände auf und entließen sie.',
        4: 'Ausgesandt vom Heiligen Geiste, wanderten sie nach Seleuzia hinab, segelten von da nach Cypern',
        5: 'und kamen dann nach Salamis. Dort verkündeten sie das Wort Gottes in den jüdischen Synagogen. Als Gehilfen hatten sie Johannes bei sich.',
        6: 'Sie durchwanderten die ganze Insel bis nach Paphus, wo sie einen jüdischen Zauberer und Lügenpropheten mit dem Namen Barjesus trafen.',
        7: 'Er war in der Umgebung des Prokonsuls Sergius Paulus, eines ganz verständigen Mannes. Dieser ließ Barnabas und Saul zu sich kommen und verlangte danach, das Wort Gottes zu hören.',
        8: 'Doch Elymas, der Zauberer - so wird sein Name übersetzt -, trat ihnen entgegen und suchte den Prokonsul vom Glauben abzuhalten.',
        9: 'Saul aber, der auch Paulus heißt, ward erfüllt vom Heiligen Geiste, blickte ihn scharf an',
        10: 'und sprach: "O du, voll Bosheit und Arglist jeder Art, du Sohn des Teufels, Feind jeglicher Gerechtigkeit. Willst du nicht aufhören, die geraden Wege des Herrn zu verwirren?',
        11: 'Siehe, die Hand des Herrn kommt jetzt über dich; du sollst blind sein und die Sonne eine Zeitlang nicht mehr sehen können." Sogleich umfing ihn Dunkel und Finsternis, er tastete umher und suchte nach jemand, der ihn führen würde.',
        12: 'Als der Prokonsul den Vorfall sah, wurde er gläubig, ganz ergriffen von der Lehre des Herrn.',
        13: 'Von Paphus fuhren Paulus und seine Gefährten nach Perge in Pamphylien. Johannes aber trennte sich von ihnen und kehrte nach Jerusalem zurück.',
        14: 'Sie zogen von Perge aus weiter und kamen nach Antiochien in Pisidien. Am Sabbat gingen sie in die Synagoge und nahmen Platz.',
        15: 'Nachdem aus dem Gesetz und den Propheten vorgelesen war, ließen ihnen die Synagogenvorsteher sagen: "Liebe Brüder! Wenn ihr einige erbauliche Worte an das Volk zu richten habt, so redet!"',
        16: 'Da erhob sich Paulus, winkte mit der Hand und sprach: "Ihr Männer Israels und ihr, die ihr Gott fürchtet, höret!',
        17: 'Der Schutzgott unseres Volkes Israel hat unsere Väter auserwählt und hat das Volk in der Fremde, im Ägypterland, vermehrt; mit hocherhobenem Arme hat er sie von dort herausgeführt.',
        18: 'An vierzig Jahre ertrug er sie in der Wüste.',
        19: 'Sieben Völker vernichtete er im Lande Kanaan und gab ihnen deren Land zum Besitze',
        20: 'nach ungefähr vierhundertfünfzig Jahren. Dann gab er ihnen Richter bis auf den Propheten Samuel.',
        21: 'Alsdann begehrten sie sich einen König, und Gott gab ihnen Saul, den Sohn des Kis, den Mann vom Stamme Benjamin, auf vierzig Jahre.',
        22: "Nachdem er ihn verworfen hatte, erweckte er ihnen David als König. Von ihm bezeugte er: 'Gefunden habe ich David, Jesses Sohn, einen Mann nach meinem Herzen; er wird in allem meinen Willen treu erfüllen.'",
        23: 'Aus dessen Nachkommen ließ Gott, so wie es verheißen war, einen Retter für Israel auferstehen, Jesus.',
        24: 'Johannes hatte schon vor seinem Auftreten dem ganzen Volke Israel die Bußtaufe verkündigt.',
        25: "Bevor jedoch Johannes seinen Lauf vollendete, sprach er: 'Ich bin nicht der, für den ihr mich haltet. Erst nach mir kommt er; ich bin's nicht wert, ihm die Schuhe von den Füßen aufzubinden.'",
        26: 'Liebe Brüder, Söhne aus dem Geschlechte Abrahams, sowie ihr anderen, die ihr Gott fürchtet! An uns ist diese Heilsbotschaft ergangen.',
        27: 'Denn die Bewohner von Jerusalem und ihre Vorsteher erkannten ihn Jesus nicht: sie brachten vielmehr die Stimmen der Propheten, die jeden Sabbat verlesen werden, durch ihren Richterspruch zur Erfüllung.',
        28: 'Obgleich sie keine Todesschuld an ihm gefunden hatten, verlangten sie doch von Pilatus, daß er getötet werden solle.',
        29: 'Als sie dann all das, was über ihn geschrieben stand, erfüllt hatten, nahm man ihn vom Holze ab und legte ihn ins Grab.',
        30: 'Doch Gott erweckte ihn am dritten Tage von den Toten.',
        31: 'Und er erschien durch eine Reihe Tage denen, die mit ihm von Galiläa nach Jerusalem hinaufgezogen waren; sie sind jetzt seine Zeugen vor dem Volke.',
        32: 'Und wir verkünden euch die frohe Botschaft, daß Gott jetzt die Verheißung, die er einst den Vätern gegeben hatte,',
        33: "an uns, den Kindern, erfüllt hat, dadurch, daß er Jesus auferweckte. So steht es auch im zweiten Psalm geschrieben: 'Mein Sohn bist Du, heute habe ich Dich gezeugt.'",
        34: "Und daß er ihn von den Toten auferweckte, damit er nicht der Verwesung überliefert würde, das sprach er also aus: 'Die unverbrüchlichen Heilsgüter Davids will ich euch verleihen.'",
        35: "So sagte er auch an einer anderen Stelle: 'Du wirst Deinen Heiligen nicht erfahren lassen die Verwesung.'",
        36: 'Doch David starb, nachdem er dem Willen Gottes in seiner Zeit gedient hatte. Er ward zu seinen Vätern versammelt und erfuhr an sich die Verwesung.',
        37: 'Der aber, den Gott von den Toten auferweckte, hat die Verwesung nicht erfahren.',
        38: 'So wisset denn, ihr Brüder, daß euch durch diesen Nachlaß der Sünden verkündet wird. Von allem, wovon ihr durch das Gesetz des Moses nicht habt gerechtfertigt werden können,',
        39: 'wird in diesem jeder, der da glaubt, gerechtfertigt.',
        40: 'Darum seht wohl zu, daß über euch nicht das komme, was bei den Propheten gesagt ist:',
        41: "'Seht, ihr Verächter, staunt und vergeht; ein Werk vollbringe ich in euren Tagen, ein Werk, das ihr nicht glauben würdet, wenn einer es euch nur erzählte.'",
        42: 'Als sie hinausgingen, bat man sie, sie möchten am nächsten Sabbat wieder über diesen Gegenstand reden.',
        43: 'Dann löste sich die Versammlung auf. Viele Juden und gottesfürchtige Proselyten folgten dem Paulus und dem Barnabas. Diese redeten ihnen eindringlich zu, in der Gnade Gottes zu verharren.',
        44: 'Am folgenden Sabbat fand sich fast die ganze Stadt ein, um das Wort Gottes zu hören.',
        45: 'Da nun die Juden die Scharen sahen, wurden sie voll Eifersucht; sie widersprachen dem, was Paulus sagte, und stießen Schmähungen aus.',
        46: 'Paulus und Barnabas aber erklärten voll Freimut: "Euch mußte das Wort Gottes zuerst gepredigt werden. Doch weil ihr es zurückweist und euch des ewigen Lebens selbst nicht würdig achtet, so wenden wir uns an die Heiden.',
        47: 'Denn also hat der Herr uns anbefohlen: \'Ich habe dich zum Lichte für die Heiden bestimmt, daß du zum Heile seist bis an die Grenzen der Erde.\'"',
        48: 'Als dies die Heiden hörten, freuten sie sich und priesen das Wort des Herrn. Alle, die für das ewige Leben bestimmt waren, wurden gläubig.',
        49: 'Das Wort des Herrn aber verbreitete sich in jener ganzen Gegend.',
        50: 'Die Juden indessen hetzten die vornehmen gottesfürchtigen Frauen und die angesehensten Männer der Stadt auf, erregten eine Verfolgung gegen Paulus und Barnabas und vertrieben sie aus ihrem Gebiet.',
        51: 'Diese aber schüttelten den Staub von ihren Füßen gegen sie und begaben sich nach Ikonium.',
        52: 'Die Jünger aber waren voll Freude und voll Heiligen Geistes.',
    },
    14: {
        1: 'In Ikonium gingen sie ebenfalls in die jüdische Synagoge und predigten, So daß eine große Menge von Juden und Heiden gläubig wurde.',
        2: 'Die Juden aber, die ungläubig blieben, reizten und erbitterten die Heiden gegen die Brüder.',
        3: 'Trotzdem konnten Sie dort noch eine Zeitlang bleiben und predigten freimütig im Vertrauen auf den Herrn, der für das Wort seiner Gnade Zeugnis gab durch Zeichen und Wunder, die er durch ihre Hände geschehen ließ.',
        4: 'Da spaltete sich die Bevölkerung der Stadt; die einen hielten es mit den Juden, die anderen mit den Aposteln.',
        5: 'Als aber bei Heiden und Juden unter Anführung ihrer Vorsteher eine Bewegung entstand, sie zu mißhandeln und zu steinigen,',
        6: 'brachten sie sich, sobald sie das merkten, in den Städten Lykaoniens in Sicherheit: in Lystra, Derbe und in deren Umgegend.',
        7: 'Dort verkündigten sie nun das Evangelium.',
        8: 'In Lystra saß ein Mann da, kraftlos an seinen Füßen von Geburt an; er hatte niemals gehen können.',
        9: 'Dieser hörte der Predigt des Paulus aufmerksam zu. Der aber blickte ihn an, sah, daß er Glauben hatte, um geheilt werden zu können,',
        10: 'und sprach zu ihm mit lauter Stimme: "Stell dich aufrecht auf deine Füße!" Und er sprang auf und ging umher.',
        11: 'Als die Volksscharen sahen, was Paulus getan hatte, erhoben sie ihre Stimmen und riefen auf lykaonisch: "Götter in Menschengestalt sind zu uns herabgestiegen."',
        12: 'Den Barnabas nannten sie Zeus, den Paulus Hermes, weil er das Wort führte.',
        13: 'Der Priester des Zeus vor der Stadt ließ Stiere und Kränze an das Tor bringen und wollte samt den Volksscharen opfern.',
        14: 'Als die Apostel Barnabas und Paulus dies erfuhren, zerrissen sie ihre Kleider, sprangen unter das Volk',
        15: 'und riefen laut: "Ihr Männer! Was macht ihr da? Auch wir sind schwache Menschen wie ihr. Wir bringen euch die frohe Botschaft, damit ihr von diesen nichtigen Götzen euch bekehren sollt zu dem lebendigen Gott, der Himmel, Erde, Meer und alles, was darinnen ist, erschaffen hat.',
        16: 'In den vergangenen Zeiten ließ er alle Völker ihre eigenen Wege gehen.',
        17: 'Gleichwohl hat er sich nicht unbezeugt gelassen: Er spendete Wohltaten: Vom Himmel her gibt er euch Regen und fruchtbare Zeiten, er schenkt euch Nahrung und erfüllt eure Herzen mit Frohsinn."',
        18: 'Nur mit Mühe konnten sie durch diese Worte die Volkscharen abhalten, ihnen Opfer darzubringen.',
        19: 'Dann kamen aber Juden von Antiochien und Ikonium her und brachten das Volk auf ihre Seite. Sie steinigten den Paulus und schleiften ihn zur Stadt hinaus, weil sie ihn für tot hielten.',
        20: 'Wie nun die Jünger um ihn herum standen, erhob er sich und kehrte in die Stadt zurück. Am folgenden Tage ging er mit Barnabas weiter nach Derbe.',
        21: 'Sie verkündeten in dieser Stadt das Evangelium und gewannen viele Jünger. Dann kehrten sie über Lystra und Ikonium wieder nach Antiochien zurück.',
        22: 'Sie stärkten dabei die Herzen der Jünger, ermahnten sie, im Glauben zu beharren, und wiesen sie darauf hin, daß wir durch viele Drangsale in das Reich Gottes eingehen müßten.',
        23: 'Sie stellten in jeder Gemeinde unter Handauflegung mit Gebet und Fasten Presbyter für sie auf und empfahlen sie dem Herrn, dem sie sich gläubig zugewandt hatten.',
        24: 'Sie kamen dann über Pisidien nach Pamphylien',
        25: 'und verkündeten das Wort des Herrn in Perge. Von da reisten sie nach Attalia hinab.',
        26: 'Hier gingen sie nach Antiochien in See. Dort hatte man sie ja der Gnade Gottes übergeben zu dem Werke, das sie nun vollendet hatten.',
        27: 'Nach ihrer Ankunft versammelten sie die Gemeinde und erzählten, welch große Dinge Gott durch sie gewirkt und daß er den Heiden die Tür des Glaubens geöffnet habe.',
        28: 'Sie verweilten geraume Zeit bei den Jüngern.',
    },
    15: {
        1: 'Da kamen einige aus Judäa herab und wollten die Brüder belehren: "Wenn ihr euch nicht nach dem Brauche des Moses beschneiden lasset, so könnt ihr das Heil nicht erlangen."',
        2: 'Es entstand eine Aufregung, und Paulus und Barnabas hatten nicht wenig gegen sie zu streiten. Da beschloß man, Paulus und Barnabas, sowie einige andere aus ihrer Mitte, sollten wegen dieser Streitfrage zu den Aposteln und Presbytern nach Jerusalem hinaufgehen.',
        3: 'Von der Gemeinde eine Strecke Weges begleitet, zogen sie durch Phönizien und Samarien hindurch, erzählten, wie die Heiden sich bekehrt hätten, und sie bereiteten allen Brüdern große Freude.',
        4: 'In Jerusalem angekommen, wurden sie von der Gemeinde, den Aposteln und den Presbytern empfangen. Sie berichteten, welch große Dinge Gott durch sie gewirkt habe.',
        5: 'Einige aus der Sekte der Pharisäer, die gläubig geworden waren, standen aber auf und erklärten: "Sie müssen sich beschneiden lassen und das Gesetz des Moses halten."',
        6: 'Da versammelten sich die Apostel und die Presbyter, um über die Forderung zu beraten.',
        7: 'Nach langem Hin- und Herreden erhob sich Petrus und sprach zu ihnen: "Liebe Brüder! Ihr wißt, daß schon vor Zeiten Gott unter euch den Ratschluß kundgetan hat, daß die Heiden durch meinen Mund das Wort des Evangeliums hören und gläubig werden sollen.',
        8: 'Gott, der Herzenskenner, hat für sie Zeugnis abgelegt, indem er ihnen, wie auch uns, den Heiligen Geist verliehen hat.',
        9: 'Er machte keinen Unterschied mehr zwischen uns und ihnen, da er durch den Glauben ihre Herzen reinigte.',
        10: 'Weshalb wollt ihr jetzt Gott versuchen und den Jüngern ein Joch auf den Nacken legen, das weder unsere Väter noch wir ertragen konnten?',
        11: 'Wir glauben vielmehr, zum Heile zu kommen durch die Gnade des Herrn Jesus Christus in gleicher Weise wie auch sie."',
        12: 'Die ganze Versammlung schwieg. Sie lauschten dem Barnabas und Paulus, die erzählten, welch große Zeichen und Wunder Gott durch sie unter den Heiden gewirkt habe.',
        13: 'Als sie zu Ende waren, ergriff Jakobus das Wort und sprach: "Liebe Brüder! Schenkt mir Gehör!',
        14: 'Symeon hat erzählt, wie Gott erstmals darauf gesehen hat, aus den Heiden ein Volk für seinen Namen zu gewinnen.',
        15: 'Es stimmen damit auch die Worte der Propheten überein wie geschrieben steht:',
        16: "'Ich komme danach wieder, um das zerfallene Zelt Davids wieder aufzurichten und, was zerstört war, wiederherzustellen und dieses wieder hinzustellen,",
        17: "damit auch die anderen Menschen den Herrn suchen, ja, alle Völker, über die mein Name genannt wird; so spricht der Herr, der solches tut.'",
        18: 'Dies ist seit Ewigkeit kund.',
        19: 'So meine ich nun, man solle denen, die vom Heidentum sich zu Gott bekehren, keine weiteren Lasten aufbürden,',
        20: 'vielmehr ihnen jetzt nur ein Schreiben senden, sie sollen von Befleckung durch die Götzen, von Unzucht, von dem Genusse des Erstickten und des Blutes sich enthalten.',
        21: 'Denn Moses hat von alters her in jeder Stadt schon seine Prediger, da in den Synagogen an allen Sabbaten aus ihm vorgelesen wird."',
        22: 'Hierauf beschlossen die Apostel und Presbyter samt der ganzen Gemeinde, aus ihrer Mitte Männer auszuwählen und sie mit Paulus und Barnabas nach Antiochien zu senden. Es waren: Judas mit dem Beinamen Barsabbas und Silas, Männer, die unter den Brüdern eine führende Stellung einnahmen.',
        23: 'Man gab ihnen folgendes Schreiben mit: "Die Apostel und die Presbyter entbieten als Brüder ihren Brüdern aus dem Heidentum in Antiochien, Syrien und Cilizien ihren Gruß.',
        24: 'Wir haben erfahren, daß einige aus unserer Mitte euch mit ihren Reden in Verwirrung und Unruhe gebracht haben. Wir hatten ihnen keinen Auftrag dazu gegeben.',
        25: 'So haben wir uns denn versammelt und beschlossen, Männer auszuwählen und sie zugleich mit unserem geliebten Barnabas und Paulus zu euch zu senden,',
        26: 'Männern, die ihr Leben eingesetzt haben für den Namen unseres Herrn Jesus Christus.',
        27: 'Wir haben demnach den Judas und den Silas abgesandt, die euch mündlich dasselbe zu verkünden haben:',
        28: 'Es hat dem Heiligen Geist und uns gefallen, euch keine weiteren Lasten aufzubürden außer folgenden notwendigen Stücken:',
        29: 'Ihr sollt euch vom Götzenopfer enthalten, von Blut, von Ersticktem und von Unzucht. Wenn ihr euch davor bewahrt, werdet ihr recht handeln. Lebt wohl!"',
        30: 'Also wurden sie entlassen und zogen nach Antiochien hinab. Sie versammelten die Gemeinde und übergaben das Schreiben.',
        31: 'Man las es und freute sich aber die beruhigenden Worte.',
        32: 'Judas und Silas, die zugleich Propheten waren, stärkten und ermunterten die Brüder durch viele Ansprachen.',
        33: 'Erst nachdem sie längere Zeit verweilt hatten, wurden sie von den Brüdern mit Friedensgrüßen zu ihren Auftraggebern entlassen.',
        34: 'Silas entschloß sich, dort zu bleiben; Judas indessen kehrte allein nach Jerusalem zurück.',
        35: 'Paulus und Barnabas aber blieben in Antiochien, lehrten und verkündeten mit noch vielen anderen das Wort des Herrn.',
        36: 'Nach einiger Zeit sprach Paulus zu Barnabas: "Wir wollen nachsehen, wie es den Brüdern in all den Städten geht, in denen wir das Wort des Herrn verkündet haben."',
        37: 'Barnabas wollte noch den Johannes, der Markus genannt wird, mitnehmen.',
        38: 'Paulus aber wollte den, der sie in Pamphylien verlassen und an ihrem Wirken nicht teilgenommen hatte, nicht um sich wissen.',
        39: 'Es kam zu einer heftigen Auseinandersetzung, so daß sie sich voneinander trennten. Barnabas fuhr mit Markus nach Cypern;',
        40: 'Paulus aber wählte sich den Silas und reiste ab, von den Brüdern der Gnade des Herrn empfohlen.',
        41: 'Er durchzog Syrien und Cilizien und stärkte die Gemeinden indem er befahl, die Vorschriften der Apostel und der Ältesten zu beobachten.',
    },
    16: {
        1: 'Er kam auch nach Derbe und Lystra. Hier war ein Jünger namens Timotheus, der Sohn einer gläubig gewordenen Jüdin und eines heidnischen Vaters.',
        2: 'Die Brüder in Lystra und Ikonium stellten ihm ein gutes Zeugnis aus,',
        3: 'und Paulus wünschte, ihn als Begleiter mitzunehmen. Mit Rücksicht auf die Juden, die in jenen Gegenden lebten, beschnitt er ihn; denn alle wußten, daß sein Vater ein Heide war.',
        4: 'Als sie nun durch die Städte wanderten, übergaben sie ihnen die von den Aposteln und Presbytern in Jerusalem gefaßten Beschlüsse zur Beachtung.',
        5: 'Die Gemeinden wurden im Glauben gestärkt und nahmen täglich an Zahl zu.',
        6: 'Sie zogen dann durch Phrygien und die Landschaft von Galatien, weil ihnen vom Heiligen Geiste verwehrt wurde, das Wort Gottes in Asien zu verkünden.',
        7: 'Sie kamen gegen Mysien hin und wollten nach Bithynien weitergehen, doch der Geist Jesu gestattete es ihnen nicht.',
        8: 'So zogen sie denn an Mysien vorbei und kamen nach Troas hinab.',
        9: 'Hier hatte Paulus in der Nacht ein Gesicht: Ein Mazedonier stand vor ihm und bat: "Komm herüber nach Mazedonien und hilf uns!"',
        10: 'Nach dieser Erscheinung suchten wir alsbald nach Mazedonien hinüberzufahren, weil wir daraus schlossen, daß Gott uns gerufen habe, um dort das Evangelium zu verkünden.',
        11: 'Wir fuhren von Troas ab, geradewegs nach Samothrake, am folgenden Tag nach Neapolis',
        12: 'und dann von da nach Philippi. Dies ist die erste Stadt in diesem Bezirk von Mazedonien, eine Kolonie. Wir hielten uns in dieser Stadt einige Tage auf.',
        13: 'Am Sabbat gingen wir vors Tor hinaus an einen Fluß, wo wir eine Gebetsstätte vermuteten. Wir setzten uns und sprachen zu den Frauen, die da zusammengekommen waren.',
        14: 'Auch eine Purpurhändlerin aus der Stadt Thyatira, namens Lydia, eine gottesfürchtige Frau, hörte zu. Ihr schloß der Herr das Herz auf, daß sie der Predigt des Paulus Aufmerksamkeit schenkte.',
        15: 'Sie ließ sich samt ihrer Familie taufen und bat: "Wenn ihr die Überzeugung habt, daß ich eine Jüngerin des Herrn bin, so kommt in mein Haus und wohnt dort." Und sie nötigte uns.',
        16: 'Auf dem Wege zur Gebetsstätte begegnete uns eines Tages eine Magd, die einen Wahrsagegeist hatte. Sie brachte durch ihre Wahrsagekunst ihrer Herrschaft großen Gewinn.',
        17: 'Sie lief hinter Paulus her und schrie: "Diese Männer sind Diener des höchsten Gottes; sie verkünden euch den Weg zum Heile."',
        18: 'So machte sie es viele Tage lang. Paulus ward sehr unwillig darüber, wandte sich um und sprach zu dem Geiste: "Ich befehle dir im Namen Jesu Christi, von ihr auszufahren." Und er fuhr aus von ihr in derselben Stunde.',
        19: 'Als nun ihre Herrschaft sah, daß die Aussicht auf Gewinn dahin sei, ergriffen sie Paulus und den Silas und schleppten sie auf den Marktplatz vor die Obrigkeit.',
        20: 'Man führte sie vor die Stadtrichter und sprach:"Diese Menschen bringen unsere Stadt in die größte Verwirrung. Sie sind Juden',
        21: 'und verkünden Gebräuche, die wir als Römer nicht annehmen noch ausüben dürfen."',
        22: 'Auch die Volksmenge erhob sich gegen mit sie. Die Stadtrichter ließen ihnen die Kleider herunterreißen und sie mit Ruten schlagen.',
        23: 'Nachdem sie ihnen viele Streiche hatten geben lassen, warfen sie beide ins Gefängnis und gaben dem Kerkermeister den Befehl, sie in sicherem Gewahrsam zu halten.',
        24: 'Auf diese Weisung hin brachte er sie in das innere Gefängnis und spannte zur Sicherheit ihre Füße in den Block.',
        25: 'Um Mitternacht sangen nun Paulus und Silas betend Gott ein Loblied. Die Gefangenen hörten ihnen zu.',
        26: 'Da entstand plötzlich ein gewaltiges Erdbeben, so daß die Grundmauern des Gefängnisses erschüttert wurden. Im Nu waren alle Tore offen, und die Fesseln fielen von allen ab.',
        27: 'Als der Kerkermeister erwachte und die Tore des Gefängnisses offenstehen sah, zog er sein Schwert und wollte sich das Leben nehmen in der Annahme, die Gefangenen seien entflohen.',
        28: 'Paulus aber rief mit lauter Stimme: "Tu dir kein Leid an; wir sind alle noch hier."',
        29: 'Er ließ sich Licht bringen, trat ein und fiel Paulus und Silas zitternd zu Füßen.',
        30: 'Er führte sie heraus und fragte: "Ihr Herren, was muß ich tun, damit ich das Heil erlange?"',
        31: 'Sie antworteten: "Glaube an den Herrn Jesus, alsdann wirst du samt deinem Hause das Heil erlangen."',
        32: 'Dann verkündeten sie ihm und seiner ganzen Familie das Wort des Herrn.',
        33: 'Noch in derselben Nachtstunde nahm er sie zu sich und wusch ihnen die Striemen ab. Auch ließ er sich sogleich samt den Seinigen taufen.',
        34: 'Dann führte er sie in sein Haus und ließ ihnen ein Mahl bereiten voll Freude, daß er mit seiner Familie zum Glauben an Gott gekommen war.',
        35: 'Als es Tag geworden war schickten die Stadtrichter Amtsdiener mit dem Befehle: "Laß diese Leute frei!"',
        36: 'Der Kerkermeister berichtete diesen Befehl dem Paulus: "Die Stadtrichter haben hergeschickt, man solle euch freilassen; so geht denn hinaus und zieht im Frieden weiter."',
        37: 'Paulus jedoch sagte zu ihnen: "Ohne Untersuchung haben sie uns, die wir doch römische Bürger sind, öffentlich schlagen und ins Gefängnis bringen lassen; und nun wollen sie uns heimlich ausweisen. Nein, sie sollen selber kommen und uns herausführen."',
        38: 'Die Amtsdiener berichteten dies den Stadtrichtern. Als diese hörten, daß sie römische Bürger seien, gerieten sie in Furcht.',
        39: 'Sie gingen hin, entschuldigten sich und führten sie heraus mit der Bitte, sie möchten die Stadt verlassen.',
        40: 'Sie verließen das Gefängnis und begaben sich zu der Lydia. Dort trafen sie Brüder, ermunterten sie und zogen danach weiter.',
    },
    17: {
        1: 'Über Amphipolis und Appolonia gelangten sie nach Thessalonich, wo die Juden eine Synagoge hatten.',
        2: 'Nach seiner Gewohnheit ging Paulus zu ihnen hinein und sprach an drei Sabbaten zu ihnen, wobei er von der Heiligen Schrift ausging.',
        3: 'Er gab ihnen Aufschluß und legte dar, daß Christus leiden und von den Toten auferstehen mußte und: "dieser ist der Christus, Jesus, den ich euch verkünde".',
        4: 'Einige aus ihnen ließen sich überzeugen und schlossen sich Paulus und Silas an, ebenso eine Anzahl gottesfürchtiger Heiden und nicht wenige vornehme Frauen.',
        5: 'Hierüber wurden die Juden aufgebracht. Sie holten Marktgesindel herbei, erregten einen Auflauf und brachten die Stadt in Aufruhr. Sie zogen vor das Haus des Jason und suchten sie, um sie dem Volke vorzuführen,',
        6: 'fanden sie aber nicht. So schleppten sie den Jason und einige Brüder vor die städtische Behörde und schrien: "Die Menschen, die die ganze Welt in Aufruhr bringen, sind auch hier.',
        7: 'Jason hat sie aufgenommen. Sie alle handeln den Verordnungen des Kaisers zuwider; sie sagen nämlich, ein anderer sei König, Jesus."',
        8: 'So reizten sie das Volk und die Behörden auf, die das mitanhörten.',
        9: 'Diese ließen sich von Jason und den übrigen Bürgschaft geben und entließen sie dann.',
        10: 'Noch in derselben Nacht schickten die Brüder den Paulus und den Silas nach Beröa weiter. Nach ihrer Ankunft begaben sie sich in die Synagoge der Juden.',
        11: 'Diese waren edler gesinnt als die in Thessalonich; sie nahmen das Wort mit aller Bereitwilligkeit an und forschten täglich in den Schriften, ob es sich auch so verhalte.',
        12: 'Viele von ihnen wurden gläubig und auch viele von den vornehmen heidnischen Frauen und Männern.',
        13: 'Als aber die Juden in Thessalonich erfuhren, daß das Wort Gottes von Paulus auch in Beröa verkündet werde, kamen sie auch dahin und brachten das Volk in Erregung und in Aufruhr.',
        14: 'Deshalb geleiteten die Brüder den Paulus sogleich scheinbar bis ans Meer, während Silas und Timotheus dort zurückblieben.',
        15: 'Die Begleiter des Paulus brachten ihn bis nach Athen. Von dort nahmen sie den Auftrag mit, Silas und Timotheus möchten so schnell wie möglich nachkommen; dann reisten sie ab.',
        16: 'Während Paulus in Athen noch auf sie wartete, ward er innerlich tief erregt, da er sah, wie die Stadt voll von Götterbildern war.',
        17: 'Er redete in der Synagoge mit den Juden und den Gottesfürchtigen und auf dem Markt tagtäglich zu denen, die gerade dorthin kamen.',
        18: 'Dabei gerieten einige epikuräische und stoische Weltweise mit ihm zusammen, und manche sagten: "Was mag wohl dieser Schwätzer sagen wollen?" Andere: "Er scheint ein Herold fremder Gottheiten zu sein." Er verkündete nämlich die frohe Botschaft von Jesus und die Auferstehung.',
        19: 'Da nahmen sie ihn mit sich und führten ihn auf den Areopag und fragten, "Dürfen wir wohl wissen, was das für eine neue Lehre ist, die du verkündest?',
        20: 'Du gibst uns ja seltsame Dinge zu hören; wir möchten nun gern wissen, welche Bewandtnis es damit habe."',
        21: 'Alle Athener und auch die Fremden, die dort wohnten, haben für nichts anderes Zeit, als das Allerneueste zu erzählen oder zu hören.',
        22: 'Da trat Paulus mitten im Areopag auf und sprach: "Ihr Männer von Athen! Ich finde, daß ihr durchaus gottesfürchtig seid.',
        23: "Denn als ich umherging und eure Götterbilder genau ansah, da fand ich einen Altar mit der Inschrift: 'Dem unbekannten Gott'. Was ihr verehrt, ohne es zu kennen, gerade das verkündige ich euch.",
        24: 'Gott, der die Welt und alles, was in ihr ist, erschaffen hat, der Herr des Himmels und der Erde, wohnt nicht in Tempeln, die von Menschenhänden gemacht sind;',
        25: 'auch läßt er sich nicht von Menschenhänden bedienen, als ob er irgend etwas brauche; er selber spendet allem Leben, Odem und gar alles.',
        26: 'Er hat aus einem Menschen das ganze menschliche Geschlecht entstehen lassen, damit es auf der ganzen Oberfläche der Erde wohne; er setzte auch die Zeiten fest und die Grenzen ihrer Wohnsitze.',
        27: 'Sie sollen Gott suchen, ob sie ihn herausfühlten und fänden, ihn, der ja keinem aus uns ferne ist.',
        28: "In ihm leben wir, bewegen wir uns und sind wir, wie es ja auch einige eurer Dichter sagen: 'Sind wir doch seines Geschlechtes'.",
        29: 'Sind wir nun so göttlichen Geschlechtes, dann dürfen wir nicht meinen, die Gottheit sei dem Golde, dem Silber und dem Steine, Erzeugnissen der bildenden Kunst und menschlicher Erfindung gleich.',
        30: 'Über die Zeiten der Unwissenheit hat Gott hinweggesehen; doch jetzt tut er den Menschen kund, daß alle allenthalben anderen Sinnes werden sollen,',
        31: 'wie er denn einen Tag festgesetzt hat, an dem er die Welt in Gerechtigkeit richten wird. Und dazu hat er einen Mann bestimmt, den er vor allem dadurch beglaubigte, daß er ihn von den Toten auferweckt hat."',
        32: 'Als sie von einer Auferstehung von den Toten hörten, spotteten einige, andere aber sagten: "Hierüber wollen wir dich ein andermal hören."',
        33: 'So ging Paulus aus ihrer Mitte hinweg.',
        34: 'Doch einige Männer schlossen sich ihm an und wurden gläubig, unter ihnen Dionysius, ein Mitglied des Areopags, und eine Frau namens Damaris und noch einige andere mit ihnen.',
    },
    18: {
        1: 'Hierauf schied Paulus von Athen und begab sich nach Korinth.',
        2: 'Dort traf er einen Juden mit Namen Aquila, der aus Pontus gebürtig und kurz zuvor aus Italien angekommen war, und dessen Frau Priszilla. Claudius hatte nämlich angeordnet, daß alle Juden Rom verlassen müßten. Zu ihnen begab er sich,',
        3: 'und weil sie das gleiche Handwerk hatten, blieb er bei ihnen und nahm dort Arbeit; sie waren nämlich von Beruf Zeltweber.',
        4: 'Jeden Sabbat sprach er in der Synagoge wobei er den Namen des Herrn Jesus einflocht und suchte Juden und Heiden zu überzeugen.',
        5: 'Als jedoch Silas und Timotheus von Mazedonien her eingetroffen waren, widmete sich Paulus ganz der Predigt und wies den Juden nach, daß Jesus der Messias ist.',
        6: 'Da sie sich aber dagegen auflehnten und Lästerungen ausstießen, schüttelte er seine Kleider aus und sprach zu ihnen: "Euer Blut komme über euer Haupt. Mich trifft keine Schuld; von nun an will ich zu den Heiden gehen."',
        7: 'Er ging von da weg und begab sich in das Haus eines gottesfürchtigen Mannes, Titius Justus mit Namen; sein Haus stieß an die Synagoge.',
        8: 'Der Synagogenvorsteher Krispus nahm mit seiner ganzen Familie den Glauben an den Herrn an. Auch viele andere Zuhörer in Korinth wurden gläubig und ließen sich taufen.',
        9: 'Es sprach aber bei Nacht der Herr in einem Gesicht zu Paulus: "Fürchte dich nicht! Rede weiterhin und schweige nicht!',
        10: 'Ich bin mit dir, und niemand soll dir weiterhin ein Leid zufügen; denn viel Volk in dieser Stadt ist mein."',
        11: 'Paulus blieb dort ein Jahr und sechs Monate und predigte unter ihnen das Wort Gottes.',
        12: 'Als Gallio Prokonsul von Achaia war, traten die Juden einmütig gegen Paulus auf, führten ihn vor den Richterstuhl',
        13: 'und erhoben die Anklage: "Der verführt die Leute, Gott in einer Weise zu verehren, die gegen das Gesetz verstößt.',
        14: 'Schon war Paulus im Begriffe zu erwidern, da sagte Gallio zu den Juden: "Würde es sich um eine Freveltat oder um ein Bubenstück handeln, ihr Juden, so würde ich eure Klage annehmen, so wie es sich gehört.',
        15: 'Handelt es sich aber um Streitigkeiten über Lehre, Namen oder über euer Gesetz, da möget ihr selbst zusehen. In solchen Dingen will ich nicht Richter sein."',
        16: 'Und er ließ sie von seinem Richterstuhl fortjagen.',
        17: 'Nun fielen alle Heiden über den Synagogenvorsteher Sosthenes her und schlugen ihn vor dem Richterstuhle. Gallio aber kümmerte sich nicht darum.',
        18: 'Paulus verblieb noch geraume Zeit. Hierauf nahm er Abschied von den Brüdern und fuhr nach Syrien. Bei ihm waren Priszilla und Aquila. In Kenchreä ließ er sich das Haupt scheren, denn er hatte ein Gelübde gemacht.',
        19: 'Sie kamen nach Ephesus, wo er sie zurückließ. Er selbst ging in die Synagoge und predigte den Juden.',
        20: 'Obwohl sie ihn baten, längere Zeit zu bleiben, ging er doch nicht darauf ein,',
        21: 'sondern nahm Abschied mit den Worten: "So Gott will, werde ich wieder zu euch kommen." - Dann reiste er von Ephesus weg',
        22: 'und kam nach Cäsarea. Von dort ging er nach Jerusalem hinauf, begrüßte die Gemeinde und begab sich dann nach Antiochien.',
        23: 'Nach einiger Zeit brach er wieder auf. Er durchwanderte nacheinander die Landschaft von Galatien und Phrygien und bestärkte alle Jünger.',
        24: 'Es war nun ein Jude namens Apollos, aus Alexandrien stammend, ein gelehrter und schriftkundiger Mann, nach Ephesus gekommen.',
        25: 'Er war in der Lehre des Herrn unterrichtet, redete mit glühender Begeisterung und lehrte genau über Jesus, obwohl er nur die Johannestaufe kannte.',
        26: 'Mit großem Freimut redete er in der Synagoge. Als Priszilla und Aquila ihn gehört hatten, nahmen sie ihn zu sich und setzten ihm die Lehre Gottes genauer auseinander.',
        27: 'Da er nach Achaia zu reisen wünschte, ermunterten ihn die Brüder und schrieben an die dortigen Jünger, sie möchten ihn gut aufnehmen. Nach seiner Ankunft leistete er den Gläubigen vortreffliche Dienste durch seine Begabung.',
        28: 'Denn schlagend widerlegte er öffentlich die Juden und wies aus der Schrift nach, daß Jesus der Christus sei.',
    },
    19: {
        1: 'Während Apollos in Korinth weilte, kam Paulus, nachdem er das Hochland durchwandert hatte, nach Ephesus. Dort traf er einige Jünger',
        2: 'und fragte sie: "Habt ihr den Heiligen Geist empfangen, als ihr gläubig wurdet?" Sie antworteten ihm: "Nein, wir haben nicht einmal gehört, daß es einen Heiligen Geist gebe."',
        3: 'Er fragte weiter: "Welche Taufe habt ihr denn empfangen?" Sie antworteten: "Die Taufe des Johannes."',
        4: 'Paulus erwiderte: "Johannes taufte zur Buße und mahnte das Volk, an den zu glauben, der nach ihm komme, nämlich Jesus."',
        5: 'Da sie dies gehört hatten, ließen sie sich auf den Namen des Herrn Jesus taufen.',
        6: 'Als Paulus ihnen dann die Hände auflegte, kam der Heilige Geist auf sie herab, sie redeten in Sprachen und weissagten.',
        7: 'Es waren im ganzen ungefähr zwölf Männer.',
        8: 'Er ging sodann in die Synagoge, predigte mit großem Freimut drei Monate hindurch und redete überzeugungsvoll vom Reiche Gottes.',
        9: 'Da aber einige in ihrem Unglauben hartnäckig verharrten, ja vor dem Volke die Lehre des Herrn lästerten, trennte er sich von ihnen und sonderte die Jünger ab. Er hielt nun täglich seine Lehrvorträge in dem Hörsaal eines gewissen Tyrannus.',
        10: 'Das währte zwei Jahre lang, so daß alle Bewohner von Asien, Juden und Heiden, Gelegenheit hatten, das Wort des Herrn zu hören.',
        11: 'Auch wirkte Gott durch die Hand des Paulus ungewöhnliche Wunder.',
        12: 'Sogar Schweißtücher und Schürzen legte man von seinem Leib weg auf die Kranken, und die Krankheiten wichen von ihnen, und die bösen Geister fuhren aus.',
        13: 'Einige der herumziehenden jüdischen Teufelsbeschwörer versuchten, über die von bösen Geistern Besessenen den Namen des Herrn Jesus anzurufen indem sie sagten: "Ich beschwöre euch bei Jesus, den Paulus verkündet."',
        14: 'Es waren die sieben Söhne des jüdischen Oberpriesters Skeuas, die es taten.',
        15: 'Aber der böse Geist erwiderte ihnen: "Jesus kenne ich, auch Paulus ist mir wohlbekannt; wer aber seid denn ihr?"',
        16: 'Damit stürzte sich der Mensch, in dem der böse Geist war, auf sie, überwältigte alle miteinander und ließ seine Macht an ihnen derart aus, daß sie nackt und wund aus jenem Hause flohen.',
        17: 'Dies wurde allen Juden und Heiden, die in Ephesus wohnten, bekannt, und Furcht kam über sie alle; der Name des Herrn Jesus aber kam hoch zu Ehren.',
        18: 'Viele Gläubige kamen, bekannten und offenbarten, was sie getan hatten.',
        19: 'Viele aber, die Zauberkünste getrieben hatten, trugen ihre Bücher zusammen und verbrannten sie vor aller Augen. Man schätzte ihren Wert insgesamt auf fünfzigtausend Silberdrachmen.',
        20: 'So breitete sich das Wort des Herrn kräftig aus und erwies sich sehr wirksam.',
        21: 'Hierauf faßte Paulus den Plan, über Mazedonien und Achaia nach Jerusalem zu reisen. "Wenn ich dort gewesen bin", sprach er, "muß ich auch Rom sehen."',
        22: 'Er sandte zwei seiner Gehilfen, Timotheus und Erastus, nach Mazedonien. Er selbst blieb noch einige Zeit in Asien.',
        23: 'Es entstand aber um jene Zeit ein ganz gewaltiger Aufruhr wegen der Lehre des Herrn.',
        24: 'Ein Silberschmied namens Demetrius verschaffte nämlich durch Anfertigung von silbernen Artemistempelchen den Handwerkern großen Verdienst.',
        25: 'Nun rief er diese und auch die anderen Arbeiter, die dasselbe Geschäft hatten, zusammen und sprach: "Ihr Männer, wie ihr wißt, fließt unser Wohlstand aus diesem Gewerbe.',
        26: 'Nun aber seht und hört ihr, wie nicht allein in Ephesus, sondern fast im ganzen Asien dieser Paulus durch seine Überredungskunst viel Volk abwendig gemacht hat. Er behauptet nämlich, das seien gar keine Götter, die mit Händen gemacht sind.',
        27: 'Es droht aber nicht nur die Gefahr, daß unser Erwerbszweig zu Schaden komme, auch das Heiligtum der großen Göttin Artemis selbst wird in Verachtung kommen; ja, sie selbst verliert an ihrer Majestät, sie, die doch ganz Asien, ja, alle Welt verehrt."',
        28: 'Da sie dies hörten, gerieten sie in Wut und schrien: "Groß ist die Artemis von Ephesus!"',
        29: 'Die Aufregung teilte sich der ganzen Stadt mit: Alles stürmte ins Theater, und man schleppte die Mazedonier Gaius und Aristarchus, Reisegefährten des Paulus, mit dahin.',
        30: 'Paulus wollte in die Volksversammlung gehen, aber die Jünger ließen ihn nicht fort.',
        31: 'Auch einige mit ihm befreundete höhere Beamte ließen ihn dringend bitten, sich nicht ins Theater zu begeben.',
        32: 'Hier schrien nun die einen dies, die anderen das; denn es herrschte in der Versammlung eine heillose Verwirrung, und die meisten wußten gar nicht, weshalb sie zusammengekommen waren.',
        33: 'Da beredete man aus der Menge einen Alexander, den die Juden vorschoben. Alexander winkte mit der Hand und wollte sich vor dem Volke verteidigen.',
        34: 'Als man aber erkannte, daß er ein Jude war, schrien sie alle wie aus einem Munde fast zwei Stunden lang: "Groß ist die Artemis von Ephesus!"',
        35: 'Endlich beschwichtigte der Stadtschreiber die Menge und hielt folgende Ansprache: "Epheser! Wer in aller Welt wüßte nicht, daß die Stadt Ephesus die Hüterin ist des Tempels der großen Artemis und ihres Bildes, das vom Himmel gefallen ist?',
        36: 'Dies ist unbestritten. Also müßt ihr Ruhe bewahren und dürft nichts Übereiltes tun.',
        37: 'Ihr habt diese Männer vorgeführt, die weder Tempelräuber noch Lästerer unserer Göttin sind.',
        38: 'Wenn Demetrius und seine Zunftgenossen Klage wider jemanden zu führen haben, so werden dafür Gerichtstage abgehalten und sind Gerichtsherren da; dort mögen sie einander verklagen.',
        39: 'Habt ihr aber noch eine weitere Beschwerde, so mag sie in einer regelrechten Volksversammlung erledigt werden.',
        40: 'Wir laufen nämlich noch Gefahr, wegen der heutigen Vorkommnisse des Aufruhrs angeklagt zu werden, da gar kein Anlaß vorhanden ist, mit dem wir diesen Auflauf rechtfertigen können." Nach diesen Worten löste er die Versammlung auf.',
    },
    20: {
        1: 'Als der Aufruhr sich gelegt hatte, beschied Paulus, die Jünger zu sich und gab ihnen Ermahnungen. Dann verabschiedete er sich und zog fort nach Mazedonien.',
        2: 'Er durchzog jene Gegend, ermahnte eindringlich die Jünger und begab sich nach Griechenland.',
        3: 'Dort war er drei Monate lang. Als er nach Syrien fahren wollte, planten die Juden einen Anschlag gegen ihn. Deshalb entschloß er sich, den Rückweg über Mazedonien zu nehmen.',
        4: 'Es begleiteten ihn bis nach Asien: Sopater, der Sohn des Pyrrhus, aus Beröa, Aristarch und Sekundus aus Thessalonich, Gaius aus Derbe, ferner Timotheus sowie Tychikus und Trophimus aus Asien.',
        5: 'Diese reisten voraus und erwarteten uns in Troas.',
        6: 'Wir aber fuhren nach den Tagen der Ungesäuerten Brote von Philippi ab und trafen sie fünf Tage später in Troas. Dort hielten wir uns sieben Tage auf.',
        7: 'Als wir nun am ersten Tage der Woche zum Brotbrechen versammelt waren, redete Paulus zu den Versammelten. Da er schon tags darauf weiterreisen wollte, dehnte er seine Rede bis Mitternacht aus.',
        8: 'Zahlreiche Lampen brannten in dem Obergemach, wo wir versammelt waren.',
        9: 'Ein Jüngling namens Eutychus saß auf der Fensterbank. Da die Predigt des Paulus sich länger hinzog, war er in tiefen Schlaf gesunken, stürzte, vom Schlaf überwältigt, vom dritten Stockwerk hinab und wurde tot aufgehoben.',
        10: 'Paulus ging hinab, beugte sich über ihn, umfaßte ihn und sagte: "Beunruhigt euch nicht, es ist noch Leben in ihm."',
        11: 'Dann ging er wieder hinauf, brach das Brot und aß. Er redete noch lange, bis zum Tagesanbruch; darauf reiste er ab.',
        12: 'Den Jüngling aber führten sie lebend herbei, und sie fühlten sich nicht wenig getröstet.',
        13: 'Wir gingen voraus auf das Schiff und segelten nach Assus weiter in der Absicht, dort den Paulus an Bord zu nehmen. So hatte er es nämlich selbst bestimmt; er selbst wollte zu Fuß dahin kommen.',
        14: 'Er traf mit uns in Assus zusammen, wir nahmen ihn an Bord und kamen nach Mytilene.',
        15: 'Von dort fuhren wir weiter und gelangten anderen Tags auf die Höhe von Chios; am nächsten Tag liefen wir Samos an übernachteten in Trogyllion und gelangten tags darauf nach Milet.',
        16: 'Paulus hatte sich nämlich entschlossen an Ephesus vorbeizufahren, um in Asien keine Zeit zu verlieren. Denn er hatte Eile, um womöglich zu Pfingsten in Jerusalem zu sein.',
        17: 'Von Milet sandte er nach Ephesus und beschied die Presbyter der Gemeinde zu sich.',
        18: 'Als sie bei ihm eingetroffen waren, sprach er zu ihnen: "Ihr wißt, wie ich vom ersten Tag an, da ich Asien betrat, die ganze Zeit bei euch verweilte.',
        19: 'Ich habe dem Herrn gedient in aller Demut unter Tränen in Prüfungen, die mir widerfahren sind durch die Nachstellungen der Juden.',
        20: 'Ich habe nichts versäumt und habe euch alles verkündigt und gelehrt, was euch zuträglich sein könnte, öffentlich, wie auch von Haus zu Haus.',
        21: 'Und ich beschwor die Juden wie die Heiden, sie möchten sich zu Gott bekehren und an unseren Herrn Jesus glauben.',
        22: 'Und jetzt fühle ich mich in meinem Innern genötigt, nach Jerusalem zu reisen. Was mir daselbst begegnet, weiß ich nicht,',
        23: 'nur das versichert mir der Heilige Geist von Stadt zu Stadt, daß Bande und Trübsal in Jerusalem meiner warten.',
        24: 'Allein, ich halte mein Leben nicht der Rede wert, wenn ich nur meinen Lauf vollende und meine Aufgabe erfülle, die ich vom Herrn Jesus erhalten habe: das Evangelium von der Gnade Gottes zu verkünden.',
        25: 'Seht, ich weiß, was mich anbetrifft, daß ihr mich nicht mehr von Angesicht zu Angesicht sehen werdet, ihr alle, bei denen ich als Prediger des Reiches wandelte.',
        26: 'Darum versichere ich es euch am heutigen Tage: Ich bin vom Blute aller rein.',
        27: 'Ich habe es gewiß nicht unterlassen, euch den ganzen Ratschluß Gottes zu verkünden.',
        28: 'Habt acht auf euch und auf die ganze Herde, in der euch der Heilige Geist zu Bischöfen bestellt hat, die Kirche Gottes zu weiden, die er für sich erworben hat mit dem Blute eines, der sein eigen ist.',
        29: 'Ich weiß: Nach meinem Weggang dringen wilde Wölfe bei euch ein und schonen nicht die Herde;',
        30: 'Ja, selbst aus eurer Mitte werden Männer auftreten, die mit verkehrten Reden die Jünger auf ihre Seite ziehen wollen.',
        31: 'So seid denn wachsam und denkt stets daran, wie ich drei Jahre lang bei Tag und Nacht nicht aufgehört habe, mit Tränen einen jeden einzeln zu mahnen.',
        32: 'Und nun empfehle ich euch Gott und dem Worte seiner Gnade. Er nur vermag es, euch aufzubauen und euch inmitten aller Heiligen das Erbe zu verleihen.',
        33: 'Silber, Gold oder Kleider habe ich von keinem einzigen begehrt.',
        34: 'Ihr wißt, daß diese meine Hände selber sorgten für das, was ich und meine Begleiter brauchten.',
        35: 'In allem habe ich euch gezeigt, daß man durch Arbeit sich der Schwachen annehmen soll, der Worte des Herrn Jesus eingedenk, wie er selbst gesagt hat: \'Geben ist seliger als Nehmen.\'"',
        36: 'Nach diesen Worten kniete er mit allen nieder und betete.',
        37: 'Alle brachen in lautes Weinen aus; sie fielen Paulus um den Hals und küßten ihn.',
        38: 'Am meisten betrübten sie sich über das Wort, als er gesagt hatte, daß sie ihn nicht mehr von Angesicht sehen würden. Sodann gaben sie ihm das Geleit bis ans Schiff.',
    },
    21: {
        1: 'Als wir uns von ihnen losgerissen hatten, fuhren wir ab. In gerader Richtung kamen wir nach Kos; tags darauf nach Rhodos und von da nach Patara.',
        2: 'Wir fanden ein Schiff, das nach Phönizien fuhr, bestiegen es und fuhren ab.',
        3: 'Wir bekamen Cypern in Sicht, ließen es links liegen, steuerten auf Syrien zu und gelangten nach Tyrus. Dort sollte das Schiff seine Fracht löschen.',
        4: 'Wir suchten die Jünger auf und blieben daselbst sieben Tage. Auf Eingebung des Geistes rieten sie dem Paulus, er solle nicht nach Jerusalem hinaufgehen.',
        5: 'Dennoch machten wir uns nach Ablauf dieser Tage auf den Weg, wobei uns alle mit Weib und Kind das Geleit gaben bis vor die Stadt hinaus. Am Strande knieten wir nieder und beteten.',
        6: 'So nahmen wir Abschied voneinander. Wir bestiegen das Schiff, jene aber kehrten nach Hause zurück.',
        7: 'Wir legten den letzten Teil unserer Seefahrt zurück und kamen von Tyrus nach Ptolemais. Dort begrüßten wir die Brüder und blieben einen Tag bei ihnen.',
        8: 'Am folgenden Tage reisten wir nach Cäsarea weiter. Wir gingen in das Haus des Evangelisten Philippus, eines der Sieben, und blieben bei ihm.',
        9: 'Dieser hatte vier Töchter, Jungfrauen, die weissagten.',
        10: 'Als wir einige Tage dort waren, kam ein Prophet namens Agabus von Judäa herab.',
        11: 'Dieser fand sich bei uns ein, nahm den Gürtel des Paulus, band sich damit Füße und Hände und sagte. "Also spricht der Heilige Geist: \'Den Mann, dem dieser Gürtel gehört, werden die Juden in Jerusalem auf solche Weise binden und den Heiden überliefern.\'"',
        12: 'Als wir das vernahmen, baten wir und die Einheimischen ihn inständig, er möge doch nicht nach Jerusalem hinaufgehen.',
        13: 'Paulus erwiderte: "Warum weint ihr und macht mir das Herz schwer? Ich bin bereit, mich nicht allein fesseln zu lassen, vielmehr auch in Jerusalem zu sterben für den Namen des Herrn Jesus."',
        14: 'Da er sich nicht überreden ließ, gaben wir nach und sprachen: "Der Wille des Herrn geschehe."',
        15: 'Nach Ablauf dieser Tage machten wir uns reisefertig und zogen nach Jerusalem hinauf.',
        16: 'Auch einige Jünger aus Cäsarea gingen mit uns und brachten uns zu einem gewissen Mnason aus Cypern, einem Jünger aus der ersten Zeit, bei dem wir gastliche Aufnahme finden sollten.',
        17: 'Als wir in Jerusalem angelangt waren, nahmen uns die Brüder mit Freuden auf.',
        18: 'Am folgenden Tage ging Paulus mit uns zu Jakobus; alle Presbyter fanden sich ein.',
        19: 'Er begrüßte sie und erzählte im einzelnen, was Gott durch seinen Dienst unter den Heiden gewirkt hatte.',
        20: 'Als sie das vernommen hatten, priesen sie Gott. Dann aber sprachen sie zu ihm: "Du siehst, lieber Bruder, wie viele Tausende bei den Juden gläubig geworden sind, und doch sind alle noch eifrige Anhänger des Gesetzes.',
        21: 'Nun haben sie von dir gehört, du lehrest alle Juden in der Heidenwelt, von Moses abzufallen, und weisest sie an, ihre Kinder nicht zu beschneiden und überhaupt nicht nach den Gesetzesbräuchen zu leben.',
        22: 'Was ist da nun zu machen? Sie werden jedenfalls in großer Zahl zusammenströmen. Sie werden ja erfahren, daß du angekommen bist.',
        23: 'So tu denn, was wir dir anraten. Bei uns sind jetzt vier Männer, die ein Gelübde auf sich haben.',
        24: 'Nimm sie zu dir, laß dich mit ihnen weihen und zahle für sie, damit sie sich das Haupt scheren lassen können. Dann werden alle einsehen, daß nichts an den Gerüchten ist, die über dich verbreitet worden sind, daß du vielmehr getreulich das Gesetz beachtest.',
        25: 'Was aber die Gläubigen aus der Heidenwelt betrifft, so haben wir den schriftlichen Bescheid gegeben, sie sollen sich enthalten von Götzenopferfleisch, von Blut, Ersticktem und von Unzucht."',
        26: 'Paulus nahm darauf die Männer zu sich, ließ sich am folgenden Tage mit ihnen weihen und ging in den Tempel. Dort meldete er den Ablauf der Weihezeit an, damit für jeden aus ihnen das Opfer dargebracht werde.',
        27: 'Als die sieben Tage zu Ende gingen, erblickten ihn Juden aus Asien im Tempel. Sie brachten das ganze Volk in Aufruhr, legten Hand an ihn und schrien:',
        28: '"Ihr Männer von Israel! Zu Hilfe! Das ist der Mensch, der überall und bei allen gegen das Gesetz und gegen diesen Ort lehrt, der sogar Heiden in den Tempel eingeführt und dadurch diese heilige Stätte entweiht hat."',
        29: 'Sie hatten nämlich vorher den Trophimus aus Ephesus mit ihm zusammen in der Stadt gesehen und meinten nun, Paulus habe ihn auch mit in den Tempel genommen.',
        30: 'Die ganze Stadt geriet in Aufruhr, und es entstand ein Volksauflauf. Sie ergriffen den Paulus und schleppten ihn aus dem Tempel, und sogleich wurden die Tore geschlossen.',
        31: 'Schon wollten sie ihn töten, da wurde dem Befehlshaber der Besatzung gemeldet, ganz Jerusalem sei in Aufruhr.',
        32: 'Dieser zog eiligst Soldaten und Hauptleute heran und eilte zu ihnen hinab. Als sie aber den Befehlshaber und die Soldaten sahen, hörten sie auf, den Paulus zu mißhandeln.',
        33: 'Der Befehlshaber trat hinzu, ließ ihn ergreifen und mit zwei Ketten fesseln. Er fragte, wer er sei und was er verbrochen habe.',
        34: 'Es rief aber in der Volksmenge alles durcheinander. Weil er vor lauter Lärm nichts Sicheres erfahren konnte, ließ er ihn auf die Burg bringen.',
        35: 'Als er an die Treppe kam, mußte er von den Soldaten getragen werden wegen des Ungestüms der Menge.',
        36: 'Denn die Volksmenge drängte nach und schrie: "Nieder mit ihm!"',
        37: 'Als Paulus eben in die Burg hinaufgeführt werden sollte, fragte Paulus den Befehlshaber: "Darf ich etwas zu dir sagen?" Jener entgegnete: "Du verstehst Griechisch?',
        38: 'So bist du also nicht der Ägypter, der neulich die viertausend Meuchelmörder aufgewiegelt und in die Wüste hinausgeführt hat?"',
        39: 'Paulus erwiderte: "Ich bin ein Jude aus Tarsus, ein Bürger dieser nicht unberühmten Stadt Ciliziens. Ich bitte dich also, gestatte mir, zum Volke zu reden."',
        40: 'Er erlaubte es. Paulus trat auf die Stufen und winkte dem Volke mit der Hand. Da trat tiefe Stille ein, und er hielt auf hebräisch folgende Ansprache:',
    },
    22: {
        1: '"Ihr Brüder und Väter! Vernehmt, wie ich mich vor euch verteidige."',
        2: 'Als sie hörten, daß er hebräisch zu ihnen sprach, wurden sie noch ruhiger.',
        3: 'Er fuhr fort: "Ich bin ein Jude, zu Tarsus in Cilizien geboren, hier in dieser Stadt erzogen zu den Füßen Gamaliels, streng nach dem väterlichen Gesetz unterrichtet. Ich war ein Eiferer für Gott, so wie ihr es alle heute seid.',
        4: 'Als solcher verfolgte ich diese Lehre bis auf den Tod und legte Männer und Frauen in Fesseln und brachte sie ins Gefängnis.',
        5: 'Das kann der Hohepriester und der ganze Rat der Ältesten mir bezeugen. Von ihnen erhielt ich Briefe an die Brüder in Damaskus und zog dorthin, um auch jene, die sich dort befanden, gefesselt nach Jerusalem zu führen, damit sie gestraft würden.',
        6: 'Als ich dahinzog und mich Damaskus näherte, umstrahlte mich plötzlich zur Mittagszeit vom Himmel her ein grelles Licht.',
        7: "Ich stürzte zu Boden und hörte eine Stimme, die mir zurief: 'Saul, Saul, warum verfolgst du mich?'",
        8: "Ich erwiderte: 'Wer bist du, Herr?' Er sprach zu mir: 'Ich bin Jesus von Nazareth, den du verfolgst.'",
        9: 'Meine Begleiter sahen zwar das Licht, doch hörten sie die Stimme nicht, die mit mir sprach.',
        10: "Ich fragte weiter: 'Was soll ich tun, o Herr?' Da sprach der Herr zu mir: 'Steh auf und geh nach Damaskus, und dort wird man dir alles sagen, was du tun sollst.'",
        11: 'Da ich nicht mehr sehen konnte wegen jenes Lichtglanzes, führten mich die Begleiter an der Hand, und also kam ich nach Damaskus.',
        12: 'Und ein gesetzestreuer Mann mit Namen Ananias, der bei allen Juden, die dort wohnen, in gutem Rufe stand, kam zu mir,',
        13: "trat herzu und sprach zu mir: 'Bruder Saul, blicke auf!' Im selben Augenblick sah ich ihn.",
        14: "Dann fuhr er fort: 'Der Gott unserer Väter hat dich dazu bestimmt, daß du seinen Willen erkennst und den Gerechten schauest und die Stimme seines Mundes vernehmest;",
        15: 'du sollst ihm Zeuge sein vor allen Menschen von dem, was du gesehen und vernommen hast.',
        16: "Und nun, was zögerst du noch? Steh auf, laß dich taufen und dich von deinen Sünden waschen, nachdem du seinen Namen angerufen hast.'",
        17: 'Als ich mich nach Jerusalem zurückbegeben hatte und im Tempel betete, geriet ich in Verzückung.',
        18: "Ich sah ihn, und er sprach zu mir: 'Verlasse eilends Jerusalem; sie werden dein Zeugnis über mich nicht annehmen.'",
        19: "Ich sprach: 'O Herr, sie wissen doch, daß ich es war, der deine Gläubigen ins Gefängnis werfen und in den Synagogen geißeln ließ.",
        20: "Als das Blut deines Zeugen Stephanus vergossen ward, da war es wieder ich, der mit Wohlbehagen dabeistand und die Kleider seiner Mörder verwahrte.'",
        21: 'Er aber sprach zu mir: \'Zieh fort; ich will dich zu den Heiden in die Ferne senden.\'"',
        22: 'Bis hierher hatten sie ihm zugehört. Nun aber schrien sie laut: "Weg von der Erde mit einem solchen Menschen. Er darf nicht mehr länger leben."',
        23: 'Als sie so schrien, ihre Kleider von sich warfen und Staub in die Höhe schleuderten,',
        24: 'befahl der Befehlshaber, den Paulus in die Burg hinaufzuführen. Zugleich gab er Befehl, ihn unter Anwendung der Folter zu verhören, um herauszubringen, warum sie so gegen ihn tobten.',
        25: 'Schon wollte man ihn in die Riemen spannen, da fragte er den Hauptmann, der dabeistand: "Ist es euch erlaubt, einen römischen Bürger, dazu noch ohne Richterspruch, zu geißeln?"',
        26: 'Als der Hauptmann das hörte, ging er zum Befehlshaber und meldete ihm: "Was hast du vor? Der Mensch dort ist römischer Bürger."',
        27: 'Der Befehlshaber trat heran und fragte ihn: "Sage mir: Bist du römischer Bärger?" Er antwortete: "Ja."',
        28: 'Der Befehlshaber entgegnete: "Ich mußte mir dieses Bürgerrecht um vieles Geld erwerben." Paulus entgegnete: "Ich besitze es schon durch Geburt."',
        29: 'Alsdann stand man davon ab, ihn zu foltern. Der Befehlshaber war sogar in Furcht, da er jetzt wußte, daß er römischer Bürger war und er ihn trotzdem hatte fesseln lassen.',
        30: 'Er wollte aber doch sicher wissen, weswegen er von den Juden angeklagt sei. Darum ließ er ihm am folgenden Tage die Fesseln abnehmen und berief die Oberpriester und den ganzen Hohen Rat. Dann ließ er Paulus hineinführen und vor sie hinstellen.',
    },
    23: {
        1: 'Festen Blickes sah Paulus auf den Hohen Rat und sprach: "Brüder! Mit dem besten Gewissen bin ich vor Gott gewandelt bis zum heutigen Tage."',
        2: 'Da befahl der Hohepriester Ananias den neben ihm Stehenden, ihn auf den Mund zu schlagen.',
        3: 'Paulus aber sprach zu ihm: "Gott wird dich schlagen, du übertünchte Wand. Du sitzest da, um mich nach dem Gesetz zu richten, und du befiehlst, mich gegen das Gesetz zu schlagen."',
        4: 'Die Umstehenden warnten: "Du beschimpfst den Hohenpriester Gottes?"',
        5: 'Paulus entgegnete: "Brüder, ich wußte nicht, daß er der Hohepriester ist; es steht ja allerdings geschrieben: \'Du sollst einen Vorsteher deines Volkes nicht schmähen.\'"',
        6: 'Nun wußte aber Paulus, daß der eine Teil Sadduzäer, der andere Pharisäer waren. Und so rief er laut in die Versammlung hinein: "Ich bin ein Pharisäer, Brüder, und stamme aus einer pharisäischen Familie. Der Hoffnung auf die Auferstehung von den Toten wegen stehe ich vor Gericht."',
        7: 'Als er dies sagte, brach ein Streit aus zwischen den Pharisäern und Sadduzäern; die Versammlung spaltete sich.',
        8: 'Die Sadduzäer leugnen nämlich, daß es eine Auferstehung, Engel und Geister gebe, die Pharisäer dagegen nehmen all dies an.',
        9: 'Es erhob sich ein großer Lärm; einige Schriftgelehrte von der Partei der Pharisäer erhoben sich, stritten heftig und erklärten: "Wir finden nichts Böses an diesem Manne. Wie, wenn ein Geist oder ein Engel zu ihm gesprochen hätte?"',
        10: 'Bei der gewaltigen Aufregung, die entstand, befürchtete der Befehlshaber, Paulus möchte von ihnen zerrissen werden. Deshalb ließ er seine Soldaten herabkommen, den Paulus aus ihrer Mitte reißen und auf die Burg führen.',
        11: 'In der folgenden Nacht erschien ihm der Herr und sprach: "Sei guten Muts! Wie du in Jerusalem Zeugnis für mich abgelegt hast, so mußt du auch in Rom Zeugnis ablegen."',
        12: 'Als es Tag geworden war, rotteten sich die Juden zusammen und verschworen sich, weder zu essen noch zu trinken, bis sie den Paulus getötet hätten.',
        13: 'Es waren mehr als vierzig, die diesen Schwur getan hatten.',
        14: 'Sie gingen zu den Oberpriestern und Ältesten und sagten: "Wir haben uns heilig verschworen, nichts zu genießen, bis wir Paulus umgebracht haben.',
        15: 'So werdet jetzt zusammen mit dem Hohen Rat beim Befehlshaber vorstellig, er möge ihn zu euch herunterführen lassen, als wolltet ihr seine Sache noch genauer untersuchen. Wir aber halten uns bereit, ihn zu töten, bevor er noch bei euch angekommen ist."',
        16: 'Allein der Schwestersohn des Paulus erfuhr von diesem Anschlag. Er verschaffte sich Eintritt in die Burg und meldete es Paulus.',
        17: 'Da ließ Paulus einen der Hauptleute kommen und bat ihn: "Führe diesen jungen Mann zum Befehlshaber; er hat ihm etwas zu melden."',
        18: 'Dieser brachte ihn zum Befehlshaber und sagte: "Der Gefangene Paulus ließ mich rufen und bat mich, diesen jungen Mann zu dir zu führen, da er dir etwas zu melden habe."',
        19: 'Der Befehlshaber nahm ihn bei der Hand, ging mit ihm auf die Seite und fragte: "Was hast du mir zu melden?"',
        20: 'Er berichtete: "Die Juden haben sich verabredet, dich zu bitten, du möchtest morgen den Paulus vor den Hohen Rat führen lassen, angeblich, um seine Angelegenheit genauer zu untersuchen.',
        21: 'Willfahre ihrer Bitte nicht. Denn über vierzig Männer aus ihnen lauern ihm auf; sie haben sich verschworen, weder zu essen noch zu trinken, bis sie ihn getötet hätten. Schon stehen sie bereit und erwarten nur noch deine Zusage."',
        22: 'Der Befehlshaber entließ den jungen Mann und schärfte ihm ein: "Sage niemand etwas davon, daß du mir dies angezeigt hast."',
        23: 'Er rief zwei von seinen Hauptleuten zu sich und befahl ihnen: "Haltet von der dritten Nachtwache an zweihundert Mann, die nach Cäsarea abmarschieren sollen, bereit, dazu noch siebzig Reiter und zweihundert Schützen."',
        24: 'Auch Reittiere sollen sie bereitstellen, um den Paulus daraufzusetzen und ihn so wohlbehalten zum Statthalter Felix zu bringen. Er befürchtete nämlich, die Juden möchten ihn ergreifen und töten, und er selbst hätte nachher die üble Nachrede zu fürchten, als hätte er sich bestechen lassen.',
        25: 'Dann schrieb er einen Brief folgenden Inhaltes:',
        26: '"Claudius Lysias entbietet dem edlen Statthalter Felix seinen Gruß.',
        27: 'Dieser Mann wurde von den Juden ergriffen und war nahe daran, von ihnen umgebracht zu werden. Da schritt ich mit meiner Mannschaft ein und befreite ihn, nachdem ich erfahren hatte, daß er ein römischen Bürger sei.',
        28: 'Da ich nun wissen wollte, weswegen sie gegen ihn Anklage erhoben hatten, ließ ich ihn vor ihren Hohen Rat bringen.',
        29: 'Da fand ich, daß er wegen Streitfragen über ihr Gesetz angeklagt war, daß aber keine Anklage gegen ihn vorliege, die Tod oder Gefängnis verdiente.',
        30: 'Es wurde mir nun angezeigt, es solle von ihnen ein Anschlag gegen den Mann ausgeführt werden. Darum sende ich ihn zu dir. Zugleich habe ich die Ankläger angewiesen, bei dir ihre Anklage gegen ihn vorzubringen. Lebe wohl!"',
        31: 'Die Soldaten brachten den Paulus ihrem Befehl gemäß in der Nacht nach Antipatris.',
        32: 'Tags darauf ließen sie die Reiter mit ihm weiterziehen und kehrten in die Burg zurück.',
        33: 'Nach ihrer Ankunft in Cäsarea überreichten sie dem Statthalter den Brief und führten ihm auch den Paulus vor.',
        34: 'Jener las den Brief und fragte den Paulus, aus welcher Provinz er stamme. Nachdem er erfahren hatte, daß er aus Cilizien sei,',
        35: 'sprach er: "Ich will dich verhören, wenn auch deine Ankläger eingetroffen sind." Dann ließ er ihn im Schlosse des Herodes in Gewahrsam halten.',
    },
    24: {
        1: 'Fünf Tage später kam der Hohepriester Ananias mit etlichen Ältesten und einem Anwalt, namens Tertyllus, um beim Statthalter die Klage gegen Paulus vorzubringen.',
        2: 'Dieser wurde vorgeladen, und Tertyllus begann mit seiner Anklagerede: "Durch dich erfreuen wir uns tiefen Friedens, deiner Fürsorge verdankt dieses Volk mannigfaltige Verbesserung.',
        3: 'Das erkennen wir allzeit und überall mit großer Dankbarkeit an, edler FeIix.',
        4: 'Um aber dich nicht länger hinzuhalten, so bitte ich dich: Schenk uns gütigst für kurze Zeit Gehör.',
        5: 'Wir haben diesen Mann als eine Pest und einen Unruhestifter unter allen Juden auf der Welt erfunden sowie als einen der Hauptführer der Nazarenersekte.',
        6: 'Ja, er hat versucht, selbst den Tempel zu entweihen. Deshalb haben wir ihn festgenommen und wollten ihn nach unserem Gesetz richten.',
        7: 'Da kam der Tribun Lysias dazwischen, entriß ihn mit großer Gewalt unseren Händen und erklärte, die Ankläger möchten zu dir kommen.',
        8: 'Du selber wirst von ihm genauere Auskunft erhalten, wenn du ihn über alles verhörst, weswegen wir ihn anklagen."',
        9: 'Diesen Angaben schlossen sich die Juden an und versicherten, daß es sich so verhalte.',
        10: 'Auf einen Wink des Statthalters ergriff Paulus das Wort zur Entgegnung: "Weil ich weiß, daß du seit langen Jahren schon Richter über dieses Volk bist, deshalb verteidige ich guten Mutes meine Sache.',
        11: 'Wie du feststellen lassen kannst, sind es nicht mehr als zwölf Tage her, seitdem ich meine Wallfahrt nach Jerusalem gemacht habe.',
        12: 'Doch weder im Tempel noch in den Synagogen, noch in der Stadt hat man mich angetroffen, daß ich mit jemandem gestritten oder einen Volksaufruhr angestiftet hätte.',
        13: 'Sie können dir auch keinerlei Beweise für das vorbringen, wessen sie mich jetzt anklagen.',
        14: 'Doch das bekenne ich dir: Ich diene nach der Lehre, die sie eine Sekte nennen, dem Gott meiner Väter. Ich glaube alles, was im Gesetz und bei den Propheten geschrieben steht,',
        15: 'und hege zu Gott die Hoffnung, die diese hier auch teilen, daß es einstens eine Auferstehung der Gerechten und der Ungerechten geben wird.',
        16: 'Deshalb befleißige ich mich auch selbst, vor Gott und den Menschen durchweg mir ein reines Gewissen zu bewahren.',
        17: 'Nach Verlauf mehrerer Jahre bin ich hinaufgezogen, um meinem Volk Almosen auszuteilen und Opfer und Gelübde darzubringen.',
        18: 'Als ich im Tempel mich dabei einer Weihe unterzog, doch ohne Lärm und Auflauf,',
        19: 'da trafen mich einige Juden aus Asien an. Die hätten vor dir erscheinen und klagen müssen, wenn sie etwas gegen mich wüßten.',
        20: 'Oder die hier mögen doch angeben, welches Vergehen sie an mir fanden, als ich vor dem Hohen Rate stand.',
        21: 'Es müßte denn dies eine Wort nur sein, das ich, als ich vor ihnen stand, laut ausrief: \'Der Auferstehung von den Toten wegen stehe ich heute vor euch als Angeklagter.\'"',
        22: 'Obwohl Felix eine genaue Kenntnis der in Frage stehenden Lehre hatte, vertagte er doch die Sache und sagte: "Wenn der Befehlshaber Lysias herabkommt, werde ich euren Fall genauer untersuchen."',
        23: 'Er gab dem Hauptmann die Weisung, ihn in milder Haft zu halten und keinen von den Seinigen zu hindern, ihm Dienste zu leisten.',
        24: 'Einige Tage später kam Felix mit seiner Gemahlin Drusilla, einer Jüdin; er ließ den Paulus rufen und hörte ihn an über den Glauben an Christus Jesus.',
        25: 'Da er aber von Gerechtigkeit, Enthaltsamkeit und dem künftigen Gerichte sprach, ward Felix betroffen und sagte: "Für jetzt kannst du gehen; wenn ich einmal Zeit habe, werde ich dich wieder rufen lassen."',
        26: 'Zugleich hoffte er auch, von Paulus Geld zu erhalten. Deshalb ließ er ihn auch öfters kommen und unterhielt sich mit ihm.',
        27: 'Volle zwei Jahre später erhielt Felix in Porzius Festus einen Nachfolger. Felix wollte sich die Juden zum Dank verpflichten und ließ darum Paulus in der Gefangenschaft zurück.',
    },
    25: {
        1: 'Festus übernahm die Verwaltung der Provinz und begab sich drei Tage später von Cäsarea nach Jerusalem hinauf.',
        2: 'Die Oberpriester und die Angesehensten der Juden brachten ihm ihre Klagen gegen Paulus vor.',
        3: 'Sie erbaten sich die gegen ihn gerichtete Vergünstigung, er möge ihn nach Jerusalem kommen lassen. Sie stellten ihm nämlich nach, um ihn unterwegs zu töten.',
        4: 'Festus entgegnete, Paulus werde in Cäsarea verwahrt bleiben; doch gedenke er selbst, bald wieder dorthin abzureisen.',
        5: '"Dann können", so fügte er hinzu, "Bevollmächtigte aus eurer Mitte mit hinabziehen und eine Klage gegen ihn vorbringen, wenn der Mann ein Verbrechen begangen haben sollte."',
        6: 'Er hielt sich bei ihnen nicht länger als acht bis zehn Tage auf und ging dann wieder nach Cäsarea hinab. Gleich am folgenden Tage hielt er eine Gerichtssitzung, ab und ließ den Paulus vorführen.',
        7: 'Kaum war dieser erschienen, da umringten ihn die Juden aus Jerusalem und brachten eine Menge schwerer Beschuldigungen gegen ihn vor, die sie aber nicht zu beweisen vermochten.',
        8: 'Paulus dagegen sagte zu seiner Verteidigung: "Weder gegen das Gesetz der Juden noch gegen den Tempel, noch gegen den Kaiser habe ich mich irgendwie verfehlt."',
        9: 'Festus aber, der sich den Juden gefällig erweisen wollte, fragte den Paulus: "Willst du nach Jerusalem hinaufgehen und dich dort in dieser Sache von mir richten lassen?"',
        10: 'Paulus erwiderte: "Ich stehe vor dem Richterstuhl des Kaisers; da habe ich mein Urteil zu empfangen. Den Juden habe ich nichts zuleid getan; das weißt auch du ganz gut.',
        11: 'Bin ich im Unrecht und habe ich ein Verbrechen begangen, das den Tod verdient, so weigere ich mich nicht zu sterben. Ist aber nichts an den Anklagen, die diese gegen mich erheben, so darf kein Mensch mich ihnen preisgeben. Ich lege Berufung an den Kaiser ein."',
        12: 'Hierauf besprach sich Festus mit seinem Beirat und erklärte dann: "Du hast Berufung an den Kaiser eingelegt; du sollst zum Kaiser gehen."',
        13: 'Einige Tage später fanden sich der König Agrippa und Berenike zur Begrüßung des Festus in Cäsarea ein.',
        14: 'Da sie dort mehrere Tage verweilten, berichtete Festus dem König über Paulus. Er erzählte ihm: "Hier ist noch ein Gefangener aus der Zeit des Felix.',
        15: 'Bei meinem Besuch in Jerusalem wurden die Oberpriester und Ältesten der Juden seinetwegen bei mir vorstellig und forderten, daß er verurteilt würde.',
        16: "Ich erwiderte ihnen, es sei nicht Sitte bei den Römern, jemand preiszugeben, ehe der Angeklagte nicht seinen Anklägern Aug' in Aug' gegenüber gestanden und Gelegenheit gehabt habe, sich gegen die Anklage zu verteidigen.",
        17: 'Als sie dann hier eintrafen, da habe ich gleich am anderen Tag ohne Aufschub Gerichtssitzung gehalten und den Mann vorführen lassen.',
        18: 'Die Ankläger traten auf, sie brachten aber keine solchen Anschuldigungen über Verbrechen vor, wie ich sie vermutete.',
        19: 'Nur einige Streitfragen über ihre Religion hatten sie gegen ihn sowie über einen gewissen verstorbenen Jesus, der aber, wie Paulus sagt, noch leben soll.',
        20: 'Da ich dieser Streitfrage gegenüber ratlos dastand, fragte ich ihn, ob er nicht nach Jerusalem gehen und dort in dieser Sache gerichtet werden Wolle.',
        21: 'Doch da legte Paulus Berufung ein und verlangte, für die Entscheidung des Kaisers aufbewahrt zu werden. So befahl ich, ihn in Haft zu halten, bis ich ihn zum Kaiser schicken würde."',
        22: 'Da sagte Agrippa zu Festus: "Ich möchte den Mann gern einmal hören." "Morgen schon", erwiderte er, "kannst du ihn hören."',
        23: 'Am anderen Tag erschienen Agrippa und Berenike mit großem Prunk. Sie betraten mit den Obersten und Vornehmen der Stadt den Gerichtssaal. Auf Befehl des Festus wurde Paulus vorgeführt.',
        24: 'Und Festus sprach: "König Agrippa und ihr alle, die ihr hier mit anwesend seid! Hier seht ihr den Mann, um dessentwillen mich die ganze Judenschaft in Jerusalem und hier mit der lauten Forderung bestürmt, ihn nicht länger mehr am Leben zu lassen.',
        25: 'Ich habe aber festgestellt, daß er kein Verbrechen begangen hat, das den Tod verdient. Weil er aber Berufung an den Kaiser eingelegt hat, habe ich beschlossen, ihn dahin zu schicken.',
        26: 'Nun weiß ich aber meinem Herrn nichts Bestimmtes über ihn zu berichten. So habe ich ihn euch und vor allem dir, König Agrippa, vorführen lassen, damit ich nach dem Verhör weiß, was ich schreiben soll.',
        27: 'Denn es erscheint mir unvernünftig, einen Gefangenen wegzuschicken, ohne die Anklagepunkte gegen ihn anzugeben."',
    },
    26: {
        1: 'Agrippa sprach zu Paulus: "Du darfst dich jetzt verteidigen." Da streckte Paulus seine Hand aus und begann seine Verteidigungsrede.',
        2: '"König Agrippa, ich schätze mich glücklich, daß ich mich wegen all der Anklagen, die die Juden gegen mich erheben, heute vor dir verteidigen darf.',
        3: 'Du bist ja ein vorzüglicher Kenner aller jüdischen Gebräuche und Streitfragen. Ich bitte deshalb, mich in Geduld zu hören.',
        4: 'Alle Juden kennen meinen Lebenswandel unter meinem Volke von meiner Jugend an und in Jerusalem.',
        5: 'Sie kennen mich von früher her und können, wenn sie wollen, es bezeugen, daß ich gemäß der strengsten Richtung unserer Religion gelebt habe, nämlich als Pharisäer.',
        6: 'Und nun stehe ich vor Gericht wegen der Hoffnung auf die Verheißung, die von Gott an unsere Väter ergangen ist.',
        7: 'Ihrer teilhaftig zu werden, hofft unser Zwölfstämmevolk mit Sehnsucht und dient unablässig Gott bei Tag und Nacht. Um dieser Hoffnung willen, König, bin ich von den Juden angeklagt.',
        8: 'Warum wird es bei euch für unglaubhaft gehalten, daß Gott Tote auferweckt?',
        9: 'Freilich, einstens glaubte auch ich, gegen den Namen Jesus von Nazareth viel Feindseliges verüben zu müssen.',
        10: 'Das tat ich in Jerusalem; auch verschaffte ich mir Vollmacht von den Oberpriestern und ließ viele Heilige ins Gefängnis bringen und, wo es sich darum handelte, sie hinzurichten, gab ich meine Zustimmung.',
        11: 'In allen Synagogen suchte ich sie durch Strafen oftmals zur Lästerung zu zwingen; ja, in meiner maßlosen Wut gegen sie verfolgte ich sie auch bis in die auswärtigen Städte.',
        12: 'So zog ich mit Vollmacht und im Auftrag der Oberpriester auch nach Damaskus.',
        13: 'Da sah ich, König, wie am Mittag auf dem Wege vom Himmel her ein Licht, noch glänzender als die Sonne, mich selbst umstrahlte und auch die, die bei mir waren.',
        14: "Wir alle stürzten zu Boden. Und da vernahm ich eine Stimme, die in hebräischer Sprache mir zurief: 'Saul, Saul, warum verfolgst du mich? Es wird dir schwer sein, gegen den Stachel auszuschlagen.'",
        15: "Ich aber fragte: 'Herr, wer bist du?' Er gab zur Antwort: 'Ich bin Jesus, den du verfolgst.",
        16: 'Doch nun steh auf und stelle dich auf deine Füße! Denn dazu bin ich dir erschienen, um dich zum Diener und zum Zeugen dessen zu bestellen, was du gesehen hast und was ich dir noch offenbaren werde.',
        17: 'Ich will dich aus dem Volke retten und auch aus den Heiden, zu denen ich dich sende.',
        18: "Du sollst ihnen die Augen öffnen, damit sie sich aus der Finsternis zum Licht und aus der Macht des Satans zu Gott bekehren, damit sie Verzeihung ihrer Sünden und Anteil mit den Heiligen erhalten dadurch, daß sie an mich glauben.'",
        19: 'Sonach konnte ich, König Agrippa, der himmlischen Erscheinung nicht ungehorsam sein.',
        20: 'Ich predigte zuerst denen in Damaskus und in Jerusalem, dann in der ganzen Landschaft Judäa und endlich bei den Heiden, sie sollten sich bekehren und sich Gott zuwenden und Werke tun entsprechend der Bekehrung.',
        21: 'Deshalb ergriffen mich die Juden im Tempel und suchten mich zu töten.',
        22: 'Doch da mir bis auf diesen Tag Gott seine Hilfe lieh, so lege ich aufrecht vor klein und groß mein Zeugnis ab, daß ich nichts anderes sage als was schon die Propheten und Moses geweissagt haben:',
        23: 'Der Messias werde leiden, als Erster von den Toten auferstehen und dem Volke wie den Heiden das Licht verkünden."',
        24: 'Da Paulus dies zu seiner Verteidigung sagte, rief Festus laut aus: "Du bist von Sinnen, Paulus! Das viele Studieren bringt dich ganz um den Verstand."',
        25: 'Paulus erwiderte: "Edler Festus, ich bin nicht von Sinnen; nein, wahr und wohlbedacht sind meine Worte.',
        26: 'Der König kennt sich in diesen Dingen sehr wohl aus, weshalb ich mit allem Freimut vor ihm rede; denn ich kann nicht glauben, es sei ihm etwas davon unbekannt geblieben, die Sache trug sich ja nicht in einem abgelegenen Winkel zu.',
        27: 'König Agrippa, glaubst du den Propheten? Ich weiß, du glaubst."',
        28: 'Agrippa erwiderte dem Paulus: "Fast überredest du mich, Christ zu werden."',
        29: 'Paulus entgegnete: "Wollte Gott, daß über kurz oder lang nicht nur du allein, nein alle, die mich heute hören, so würden, wie ich bin, nur abgesehen von diesen Ketten da."',
        30: 'Da erhoben sich der König, der Statthalter, Berenike und die übrigen Anwesenden.',
        31: 'Im Weggehen sprachen sie zueinander: "Dieser Mensch hat nichts getan, was Tod oder Gefängnis verdiente."',
        32: 'Und Agrippa sagte zu Festus: "Man könnte den Mann freilassen, hätte er nicht Berufung an den Kaiser eingelegt."',
    },
    27: {
        1: 'Als unsere Abfahrt nach Italien festgesetzt war, wurde Paulus mit noch einigen anderen Gefangenen einem Hauptmann der kaiserlichen Kohorte, namens Julius, übergeben.',
        2: 'Wir bestiegen ein adramyttenisches Schiff, das die asiatischen Küstenplätze anlaufen sollte, und fuhren ab. Mit uns fuhr noch Aristarch aus Thessalonich in Mazedonien.',
        3: 'Am folgenden Tage landeten wir in Sidon. Julius behandelte den Paulus rücksichtsvoll und gestattete ihm, die Freunde aufzusuchen und sich mit dem Nötigen versehen zu lassen.',
        4: 'Von da segelten wir ab und fuhren an Cypern hin, weil wir widrigen Wind hatten.',
        5: 'So durchfuhren wir das Meer bei Cilizien und Pamphylien und kamen nach Myra in Lykien.',
        6: 'Dort fand der Hauptmann ein alexandrinisches Schiff, das sich auf der Fahrt nach Italien befand, und brachte uns hinüber.',
        7: 'Nach vielen Tagen langsamer Fahrt kamen wir mit Mühe gegen Knidos hin, und da der Wind uns dort nicht anlegen ließ, fuhren wir an Kreta hin, auf der Höhe von Salmone.',
        8: 'Nach mühevoller Fahrt längs der Küste kamen wir an einen Ort Kaloi Limenes in der Nähe der Stadt Lasäa.',
        9: 'Unterdessen war geraume Zeit verstrichen, und die Schiffahrt wurde bereits gefährlich; der Fasttag war ja schon vorüber. Darum warnte sie Paulus:',
        10: '"Ihr Männer, ich sehe, daß die Schiffahrt mit großem Ungemach und großem Schaden nicht bloß für die Ladung und das Schiff, sondern auch für unser Leben vor sich gehen wird."',
        11: 'Der Hauptmann gab aber auf die Worte des Steuermanns und des Schiffsherrn mehr als auf die des Paulus.',
        12: 'Da der Hafen zum Überwintern nicht günstig war, beschloß die Mehrzahl, von da ins offene Meer zu fahren, um womöglich Phönix zu erreichen und dort zu überwintern. Dieser Hafen Kretas ist gegen Südwest und Nordwest geschützt.',
        13: 'Da ein schwacher Südwind aufkam, glaubten sie, mit ihrem Vorhaben sicher zum Ziel zu kommen; sie lichteten die Anker und fuhren dicht an der Küste Kretas hin.',
        14: 'Doch nach kurzer Zeit brach von der Insel her ein Sturmwind los, ein sogenannter Ostnordost.',
        15: 'Das Schiff wurde von ihm erfaßt und konnte dem Sturm nicht standhalten; so gaben wir es preis und ließen uns treiben.',
        16: 'Wir kamen an einer kleinen Insel, Klauda, vorbei. Dort gelang es uns mit vieler Mühe, des Rettungsbootes habhaft zu werden.',
        17: 'Man zog es herauf und wandte Schutzmittel an, indem man das Schiff untergürtete. Aus Furcht, in die Syrte zu geraten, zog man die Segel ein und ließ sich so dahintreiben.',
        18: 'Der Sturm setzte uns furchtbar zu. Deshalb warf man am folgenden Tag einen Teil der Ladung über Bord;',
        19: 'am dritten Tage schleuderten die Leute eigenhändig das Schiffsgerät hinaus.',
        20: 'Mehrere Tage sah man weder Sonne noch Sterne; der Sturm tobte ungeschwächt weiter; alle Hoffnung auf Rettung war geschwunden.',
        21: 'Schon lange hatten die Leute nichts mehr zu sich genommen, da trat Paulus mitten unter sie und sagte: "Ihr Männer, man hätte mir folgen und nicht von Kreta in das offene Meer hinausfahren sollen, dann wären uns dieses Ungemach und dieser Schaden erspart geblieben.',
        22: 'Für jetzt jedoch ermahne ich euch, guten Mutes zu sein. Kein Menschenleben aus uns wird verlorengehen, sondern nur das Schiff.',
        23: 'Denn heute nacht erschien mir ein Engel des Gottes, dem ich zu eigen bin und dem ich diene,',
        24: "und sprach: 'Fürchte dich nicht, Paulus! Du mußt vor den Kaiser treten. Siehe, Gott hat dir alle geschenkt, die mit dir fahren.'",
        25: 'Darum seid guten Mutes, ihr Männer! Denn ich vertraue auf Gott, daß es so kommen wird, wie es mir verheißen ward.',
        26: 'Wir müssen auf irgendeine Insel verschlagen werden."',
        27: 'Als wir schon die vierzehnte Nacht im Adriatischen Meer umhertrieben, vermuteten um Mitternacht die Schiffsleute Land in der Nähe.',
        28: 'Sie warfen das Senkblei und warfen eine Tiefe von zwanzig Faden. Als sie nach kurzer Zeit wiederum das Senkblei warfen, fanden sie nur noch fünfzehn.',
        29: 'Aus Furcht, wir möchten auf Klippen auflaufen, warfen sie vom Hinterteil des Schiffes vier Anker aus und erwarteten sehnlichst den Anbruch des Tages.',
        30: 'Da machte die Besatzung den Versuch, vom Schiffe zu fliehen. Sie ließen das Rettungsboot ins Meer nieder unter dem Vorwand, sie wollten auch vom Vorderteil aus Anker auswerfen.',
        31: 'Paulus aber sagte dem Hauptmann und den Soldaten: "Wenn diese nicht auf dem Schiffe bleiben, könnt ihr nicht gerettet werden."',
        32: 'Da hieben die Soldaten die Taue des Rettungsbootes ab und ließen es ins Meer fallen.',
        33: 'Sobald der Morgen dämmerte, ermahnte Paulus alle, Nahrung zu sich zu nehmen. Er sprach: "Heute werden es vierzehn Tage, daß ihr ohne Nahrung in einem fort nur wartet, ohne etwas zu genießen.',
        34: 'Darum rate ich euch, jetzt Nahrung zu euch zu nehmen; das dient zu eurer Rettung. Keinem von euch wird auch nur ein Haar von seinem Haupte verlorengehen,',
        35: 'Nach diesen Worten nahm er Brot, dankte Gott vor aller Augen, brach es und fing an zu essen.',
        36: 'Da bekamen alle Mut und nahmen ebenfalls Nahrung zu sich.',
        37: 'Im ganzen waren wir zweihundertsechsundsiebzig Personen an Bord.',
        38: 'Als sie sich gesättigt hatten, erleichterten sie das Schiff, indem sie die Getreideladung ins Meer warfen.',
        39: 'Endlich ward es heller Tag, doch sie erkannten das Land nicht. Sie bemerkten aber eine Bucht mit einem flachen Strande. Dorthin gedachten sie, wenn möglich, das Schiff auflaufen zu lassen.',
        40: 'Sie machten also die Anker los und ließen sie ins Meer fallen; zugleich lösten sie die Riemen von den Rudern, stellten das Vordersegel nach dem Wind und hielten auf den Strand zu.',
        41: 'Sie gerieten auf eine Landzunge, wo sie das Schiff auflaufen ließen. Das Vorderteil bohrte sich tief ein und saß fest; das Hinterteil jedoch wurde durch den Anprall der Wogen zerschellt.',
        42: 'Die Soldaten waren nun willens, die Gefangenen zu töten, damit keiner durch Schwimmen entkomme.',
        43: 'Allein der Hauptmann, der Paulus retten wollte, hinderte sie an ihrem Vorhaben. Er befahl, wer Schwimmen könne, solle zuerst hinausspringen und ans Land gehen,',
        44: 'die übrigen teils auf Brettern, teils auf sonstigen Schiffstrümmern. So gelang es, alle unversehrt ans Land zu retten.',
    },
    28: {
        1: 'Als wir gerettet waren, erfuhren wir, daß die Insel Malta hieß..',
        2: 'Die Eingeborenen erwiesen uns eine ungewöhnliche Menschenfreundlichkeit. Sie zündeten ein Feuer an und holten uns alle heran, denn Regen setzte ein, und es war kalt.',
        3: 'Paulus raufte einen Haufen Reisig zusammen und warf ihn ins Feuer. Da schnellte infolge der Hitze eine Natter heraus und heftete sich an seine Hand.',
        4: 'Als die Eingeborenen das Tier an seiner Hand hängen sahen, sprachen sie zueinander: "Gewiß ist dieser Mensch ein Mörder. Wenn er auch dem Meer entronnen ist, die Rache läßt ihn dennoch nicht am Leben."',
        5: 'Er aber schüttelte das Tier ins Feuer, ohne daß er Schaden erlitten hatte.',
        6: 'Die Leute warteten nun darauf, daß er anschwellen oder plötzlich tot zusammensinken werde. Lange warteten sie. Als sie sahen, daß ihm nichts Schlimmes widerfuhr, änderten sie ihre Ansicht und sagten, er sei ein Gott.',
        7: 'In jener Gegend besaß der oberste Beamte der Insel, namens Publius, ein Landgut. Dieser nahm uns auf und gewährte uns drei Tage lang liebevolle Gastfreundschaft.',
        8: 'Der Vater des Publius lag gerade an fiebriger Ruhr krank danieder. Paulus ging zu ihm hin, betete, legte ihm die Hand auf und machte ihn gesund.',
        9: 'Daraufhin kamen auch die anderen Kranken der Insel herbei und wurden geheilt.',
        10: 'Dafür überhäufte man uns mit Ehrenbezeigungen und versah uns bei unserer Abfahrt mit allem, was wir nötig hatten.',
        11: 'Nach drei Monaten fuhren wir auf einem alexandrinischen Schiff ab. Dieses hatte auf der Insel überwintert und führte das Zeichen der Dioskuren.',
        12: 'Wir liefen Syrakus an, wo wir drei Tage blieben.',
        13: 'Von dort fuhren wir der Küste entlang und kamen nach Rhegium. Da tags darauf ein Südwind einsetzte, kamen wir in zwei Tagen nach Puteoli.',
        14: 'Dort trafen wir Brüder, die uns baten, sieben Tage bei ihnen zu bleiben. Und dann kamen wir nach Rom.',
        15: 'Die Brüder hatten von uns gehört und kamen uns von dort entgegen bis Forum Appii und Tres Tabernae. Bei ihrem Anblick dankte Paulus Gott und schöpfte neuen Mut.',
        16: 'Nachdem wir in Rom angekommen waren übergab der Hauptmann die Gefangenen dem Befehlshaber des Lagers, wurde es dem Paulus gestattet, unter Aufsicht eines Soldaten eine eigene Wohnung zu beziehen.',
        17: 'Nach drei Tagen rief er die Angesehensten der Juden zu sich. Als sie versammelt waren, sprach er zu ihnen: "Brüder, ohne mich gegen das Volk oder die Vätersitte je verfehlt zu haben, bin ich von Jerusalem aus als Gefangener den Römern überliefert worden.',
        18: 'Sie wollten mich nach einer Untersuchung in Freiheit setzen, weil kein todeswürdiges Verbrechen bei mir vorlag.',
        19: 'Jedoch die Juden legten Einspruch ein, und so war ich genötigt, Berufung an den Kaiser einzulegen, jedoch nicht, als wollte ich mein Volk selbst verklagen.',
        20: 'Aus diesem Grunde also habe ich euch zu mir gebeten, um euch zu sehen und zu sprechen; denn um der Hoffnung Israels willen bin ich mit dieser Kette umschlossen."',
        21: 'Sie erwiderten ihm-. "Wir haben weder schriftliche Nachricht aus Judäa über dich erhalten, noch kam einer von den Brüdern und berichtete oder erzählte uns etwas Nachteiliges über dich.',
        22: 'Doch möchten wir deine Ansicht näher kennenlernen. Denn von dieser Sekte ist uns nur bekannt, daß sie überall Widerspruch findet."',
        23: 'Sie bestimmten ihm einen Tag und fanden sich an ihm in größerer Anzahl in seiner Wohnung ein. Er erklärte und bezeugte ihnen das Reich Gottes und suchte sie im Anschluß an das Gesetz des Moses und an die Propheten vom frühen Morgen bis zum Abend für die Sache Jesu zu gewinnen.',
        24: 'Ein Teil glaubte seinen Worten, der andere blieb ungläubig.',
        25: 'In Uneinigkeit miteinander gingen sie weg. Paulus sagte nur noch das eine Wort: "Treffend hat der Heilige Geist zu euren Vätern durch Isaias, den Propheten, gesagt:',
        26: '\'Tritt hin vor dieses Volk und sprich "Ihr werdet hören und nicht verstehen, ihr werdet sehen und nicht einsehen;',
        27: 'verstockt ist das Herz dieses Volkes; seine Ohren sind schwerhörig, und seine Augen sind verschlossen, damit es mit den Augen ja nicht sehe und mit den Ohren nicht höre, in seinem Herzen nicht verständig werde und sich bekehre und Heilung bei mir finde."\'',
        28: 'So sei es denn euch kund, daß das Heil Gottes den Heiden gebracht wird, und diese werden darauf hören."',
        29: 'Nachdem er dies gesagt hatte, verließen ihn die Juden, wobei sie viele Streitfragen unter sich hatten.',
        30: 'Er blieb zwei volle Jahre in seiner Mietwohnung und nahm alle auf, die zu ihm kamen.',
        31: 'Er verkündete das Reich Gottes und lehrte vom Herrn Jesus Christus ganz offen und ungehindert.',
    },
}
